window.__X_NEWS__ = {"updated_at": "2026-10-22 03:05 Asia/Shanghai", "updated_at_iso": "2026-10-21T19:05:24.000Z", "count": 91, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112650189492072480", "domain": "科技", "title_en": "Blockchain Projects Form Quantum Alliance and Launch Unified Compute Platform", "title_zh": "区块链项目组建量子联盟并推出统一算力平台", "hook_en": "Blockchain teams are teaming up to shield networks from quantum threats while making quantum hardware easier for developers to use.", "hook_zh": "区块链团队联手抵御量子威胁，同时让开发者更易使用量子硬件。", "summary_en": "American Fortress joined eight other organizations to launch the Quantum Alliance, which sets open standards for post-quantum security in blockchains, wallets, and cross-chain systems. Meanwhile, Quip Network released its Quip Virtual Machine on the Aglais testnet around October 20, 2026, letting developers write one program that runs on quantum annealers like D-Wave, future gate-based systems like IonQ, and classical CPUs or GPUs. The platform verifies results on-chain and offers upfront cost quotes, with early demos showing quantum edges in portfolio optimization. Community members highlight the need for full security upgrades, transparent benchmarks, and real-world testing as these tools advance.", "summary_zh": "American Fortress 联合另外八家机构发起 Quantum Alliance，为区块链、钱包与跨链系统制定后量子安全开放标准。与此同时，Quip Network 约于 2026 年 10 月 20 日在 Aglais 测试网发布 Quip 虚拟机，开发者可写一套程序，运行于 D-Wave 等量子退火机、未来 IonQ 等门电路系统，以及经典 CPU/GPU。平台链上校验结果并提供预估报价，早期演示显示投资组合优化等场景有量子优势。社区强调需全面安全升级、透明基准与真实场景验证。", "body_en": "Blockchain Projects Form Quantum Alliance and Launch Unified Compute Platform.\n\nBlockchain teams are teaming up to shield networks from quantum threats while making quantum hardware easier for developers to use.\n\nAmerican Fortress joined eight other organizations to launch the Quantum Alliance, which sets open standards for post-quantum security in blockchains, wallets, and cross-chain systems. Meanwhile, Quip Network released its Quip Virtual Machine on the Aglais testnet around October 20, 2026, letting developers write one program that runs on quantum annealers like D-Wave, future gate-based systems like IonQ, and classical CPUs or GPUs.\n\nThe platform verifies results on-chain and offers upfront cost quotes, with early demos showing quantum edges in portfolio optimization. Community members highlight the need for full security upgrades, transparent benchmarks, and real-world testing as these tools advance.", "body_zh": "区块链项目组建量子联盟并推出统一算力平台。\n\n区块链团队联手抵御量子威胁，同时让开发者更易使用量子硬件。\n\nAmerican Fortress 联合另外八家机构发起 Quantum Alliance，为区块链、钱包与跨链系统制定后量子安全开放标准。与此同时，Quip Network 约于 2026 年 10 月 20 日在 Aglais 测试网发布 Quip 虚拟机，开发者可写一套程序，运行于 D-Wave 等量子退火机、未来 IonQ 等门电路系统，以及经典 CPU/GPU。\n\n平台链上校验结果并提供预估报价，早期演示显示投资组合优化等场景有量子优势。社区强调需全面安全升级、透明基准与真实场景验证。", "url": "https://x.com/i/trending/2112650189492072480", "category": "News", "topics": ["Technology", "Cryptocurrency"], "updated_at": "2026-10-21T17:33:03.000Z"}, {"id": "2112386205996245100", "domain": "科技", "title_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development", "title_zh": "奥特曼勾勒先进 AI 安全发展的三条路径", "hook_en": "Sam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.", "hook_zh": "萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。", "summary_en": "Last week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures. The talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "summary_zh": "上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "body_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development.\n\nSam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.\n\nLast week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures.\n\nThe talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "body_zh": "奥特曼勾勒先进 AI 安全发展的三条路径。\n\n萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。\n\n上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。\n\n谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "url": "https://x.com/i/trending/2112386205996245100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T14:10:55.000Z"}, {"id": "2112883740699480270", "domain": "科技", "title_en": "OpenAI Partners with Google Cloud to Offer Frontier Models in Model Garden", "title_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden", "hook_en": "OpenAI's powerful models like GPT-6 Astra are landing on Google Cloud, giving businesses a unified spot to access top AI tools without juggling platforms.", "hook_zh": "GPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。", "summary_en": "Google Cloud announced today that enterprise customers can soon use OpenAI's frontier models, including GPT-6 Astra and Codex agentic workflows, directly in its Model Garden alongside Gemini, Claude, and over 200 others. Businesses can purchase through the Google Cloud Marketplace, apply existing spending commitments, and integrate into tools like Google Antigravity and Gemini Agent for flexible task handling. This expands OpenAI's reach beyond Microsoft Azure—now non-exclusive—to more cloud options, supporting regulated industries with strong data governance and high-performance setup. Analysts see it as a win for multi-model strategies and easier AI adoption.", "summary_zh": "谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "body_en": "OpenAI Partners with Google Cloud to Offer Frontier Models in Model Garden.\n\nOpenAI's powerful models like GPT-6 Astra are landing on Google Cloud, giving businesses a unified spot to access top AI tools without juggling platforms.\n\nGoogle Cloud announced today that enterprise customers can soon use OpenAI's frontier models, including GPT-6 Astra and Codex agentic workflows, directly in its Model Garden alongside Gemini, Claude, and over 200 others. Businesses can purchase through the Google Cloud Marketplace, apply existing spending commitments, and integrate into tools like Google Antigravity and Gemini Agent for flexible task handling.\n\nThis expands OpenAI's reach beyond Microsoft Azure—now non-exclusive—to more cloud options, supporting regulated industries with strong data governance and high-performance setup. Analysts see it as a win for multi-model strategies and easier AI adoption.", "body_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden。\n\nGPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。\n\n谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。\n\n此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "url": "https://x.com/i/trending/2112883740699480270", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:08:05.000Z"}, {"id": "2112176711844458620", "domain": "科技", "title_en": "Anthropic Commits Shares to Public Benefit Fund", "title_zh": "Anthropic 设立公益基金，承诺拨出股份服务公共目的", "hook_en": "Anthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.", "hook_zh": "Anthropic 宣布把约 5% 股份用于公益，回应“AI 带来普遍丰裕”的期待。", "summary_en": "The AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline. Combined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "summary_zh": "这家推出 Claude 的公司宣布设立“公益基金”，起步拨出 5% 股份（须经股东批准），估值每高出基准 50% 还可再增拨最多 2%。加上此前承诺，约合 20% 股份可用于非营利捐赠、援助受影响群体或应对就业冲击等，并延续其 2 亿美元劳工研究投入，且不用于游说。埃隆·马斯克回应称自己也会这么做，并提到“普遍高收入”，引发关于如何分享 AI 红利的讨论。", "body_en": "Anthropic Commits Shares to Public Benefit Fund.\n\nAnthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.\n\nThe AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline.\n\nCombined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "body_zh": "Anthropic 设立公益基金，承诺拨出股份服务公共目的。\n\nAnthropic 宣布把约 5% 股份用于公益，回应“AI 带来普遍丰裕”的期待。\n\n这家推出 Claude 的公司宣布设立“公益基金”，起步拨出 5% 股份（须经股东批准），估值每高出基准 50% 还可再增拨最多 2%。\n\n加上此前承诺，约合 20% 股份可用于非营利捐赠、援助受影响群体或应对就业冲击等，并延续其 2 亿美元劳工研究投入，且不用于游说。埃隆·马斯克回应称自己也会这么做，并提到“普遍高收入”，引发关于如何分享 AI 红利的讨论。", "url": "https://x.com/i/trending/2112176711844458620", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:34:55.000Z"}, {"id": "2112908301625356787", "domain": "科技", "title_en": "AI Agents Uncover Brain Disease Leads in 32 Minutes", "title_zh": "AI 智能体 32 分钟挖出脑疾病新线索", "hook_en": "Thousands of AI agents pored over millions of mouse brain cells, spotting fresh clues for neurodegenerative diseases in record time.", "hook_zh": "成千上万个 AI 智能体梳理数百万小鼠脑细胞，以创纪录速度发现神经退行性疾病的新线索。", "summary_en": "OpenAI, PerturbAI, and Scripps Research used distributed GPT-Rosalind agents to analyze a massive CRISPR brain atlas. Each agent zeroed in on one gene, checked cell responses across brain regions, scanned literature, and drafted explanations—combining into a detailed atlas in just 32 minutes. Standout discoveries included DCTN1's link to cholesterol issues in Perry syndrome and differing impacts of TSC1 versus TSC2 in neuron communication, ideas human experts favored over single-agent outputs. The approach, building on OpenAI's Orchestra Bio acquisition, promises to speed up drug discovery by handling data volumes that overwhelm traditional methods.", "summary_zh": "OpenAI、PerturbAI 与 Scripps 研究所用分布式 GPT-Rosalind 智能体分析大规模 CRISPR 脑图谱。每个智能体聚焦一个基因，核对跨脑区细胞反应、检索文献并起草解释，32 分钟内汇总成详细图谱。亮点包括 DCTN1 与 Perry 综合征胆固醇问题的关联，以及 TSC1 与 TSC2 对神经元通讯影响的差异；人类专家更认可多智能体结果，而非单智能体输出。该方法依托 OpenAI 收购 Orchestra Bio 的布局，有望处理传统方法难以消化的数据量，加速药物发现。", "body_en": "AI Agents Uncover Brain Disease Leads in 32 Minutes.\n\nThousands of AI agents pored over millions of mouse brain cells, spotting fresh clues for neurodegenerative diseases in record time.\n\nOpenAI, PerturbAI, and Scripps Research used distributed GPT-Rosalind agents to analyze a massive CRISPR brain atlas. Each agent zeroed in on one gene, checked cell responses across brain regions, scanned literature, and drafted explanations—combining into a detailed atlas in just 32 minutes.\n\nStandout discoveries included DCTN1's link to cholesterol issues in Perry syndrome and differing impacts of TSC1 versus TSC2 in neuron communication, ideas human experts favored over single-agent outputs. The approach, building on OpenAI's Orchestra Bio acquisition, promises to speed up drug discovery by handling data volumes that overwhelm traditional methods.", "body_zh": "AI 智能体 32 分钟挖出脑疾病新线索。\n\n成千上万个 AI 智能体梳理数百万小鼠脑细胞，以创纪录速度发现神经退行性疾病的新线索。\n\nOpenAI、PerturbAI 与 Scripps 研究所用分布式 GPT-Rosalind 智能体分析大规模 CRISPR 脑图谱。每个智能体聚焦一个基因，核对跨脑区细胞反应、检索文献并起草解释，32 分钟内汇总成详细图谱。\n\n亮点包括 DCTN1 与 Perry 综合征胆固醇问题的关联，以及 TSC1 与 TSC2 对神经元通讯影响的差异；人类专家更认可多智能体结果，而非单智能体输出。该方法依托 OpenAI 收购 Orchestra Bio 的布局，有望处理传统方法难以消化的数据量，加速药物发现。", "url": "https://x.com/i/trending/2112908301625356787", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T16:58:22.000Z"}, {"id": "2112630070984802593", "domain": "科技", "title_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations", "title_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天", "hook_en": "Ever had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.", "hook_zh": "把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 或生物识别就能搞定。", "summary_en": "The feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile. Locked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "summary_zh": "用户可将聊天移入受保护区域，从历史、置顶与搜索中隐藏，需四位 PIN（全平台）或手机生物识别才能打开。功能自 10 月 20 日起覆盖免费到企业、教育等各档套餐的网页、桌面与移动端。锁定对话的新消息进入独立记忆分区，不影响普通聊天；但不提供端到端加密，重置 PIN 后也无法恢复。此举回应了围绕 ChatGPT 记忆与隐私的讨论。", "body_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations.\n\nEver had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.\n\nThe feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile.\n\nLocked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "body_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天。\n\n把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 或生物识别就能搞定。\n\n用户可将聊天移入受保护区域，从历史、置顶与搜索中隐藏，需四位 PIN（全平台）或手机生物识别才能打开。功能自 10 月 20 日起覆盖免费到企业、教育等各档套餐的网页、桌面与移动端。\n\n锁定对话的新消息进入独立记忆分区，不影响普通聊天；但不提供端到端加密，重置 PIN 后也无法恢复。此举回应了围绕 ChatGPT 记忆与隐私的讨论。", "url": "https://x.com/i/trending/2112630070984802593", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T08:41:04.000Z"}, {"id": "2112595601669919101", "domain": "科技", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。Samuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion.\n\nCritics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持。\n\nOpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。\n\n去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。\n\nSamuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z"}, {"id": "2112540739628630161", "domain": "科技", "title_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors", "title_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片", "hook_en": "Amazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.", "hook_zh": "大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。", "summary_en": "The company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake. This comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "summary_zh": "公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "body_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors.\n\nAmazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.\n\nThe company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake.\n\nThis comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "body_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片。\n\n大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。\n\n公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。\n\n有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "url": "https://x.com/i/trending/2112540739628630161", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "AI"], "updated_at": "2026-10-20T13:52:24.000Z"}, {"id": "2112496630352281688", "domain": "科技", "title_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage", "title_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心", "hook_en": "Microsoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.", "hook_zh": "得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。", "summary_en": "Nscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong. Nscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "summary_zh": "Nscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。Nscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "body_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage.\n\nMicrosoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.\n\nNscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong.\n\nNscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "body_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心。\n\n得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。\n\nNscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。\n\nNscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "url": "https://x.com/i/trending/2112496630352281688", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T10:54:58.000Z"}, {"id": "2112905930044317939", "domain": "科技", "title_en": "NVIDIA and University of Washington Release RFD4-Proteina for Protein Design", "title_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计", "hook_en": "Imagine designing proteins—from enzymes to antibodies—in one seamless step, 13 times faster than before. That's the breakthrough from NVIDIA and the University of Washington's Baker Lab.", "hook_zh": "英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。", "summary_en": "RFD4-Proteina, a new open AI model, reasons across amino acids, sugars, DNA, and RNA to co-design a protein's sequence and 3D structure together. Born from a year-long collaboration with Nobel laureate David Baker's team, it excels on benchmarks, speeds up generation for 200-residue proteins, and has produced real-world successes like an enzyme for the HIV drug lenacapavir. Available now on GitHub, Hugging Face, and as an NVIDIA service, it's already drawing excitement from scientists for accelerating drug discovery and enzyme engineering.", "summary_zh": "RFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "body_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design.\n\nScientists at NVIDIA and the University of Washington just dropped a powerful new AI tool that designs proteins quicker and better than before. It's already drawing cheers for speeding up drug discovery.\n\nRFD4-Proteina, born from a year-long collaboration between NVIDIA's GenAIR team and the Baker Lab at UW's Institute for Protein Design, co-designs protein sequences and structures in a shared latent space. It handles binder design, enzyme scaffolding, motif conditioning, and work with DNA, RNA, or small molecules, outperforming prior models in speed, quality, and wet-lab success rates.\n\nReleased open source on GitHub and Hugging Face at GTC Berlin, it's available as an NVIDIA NIM microservice and integrated with partners like Tamarind Bio for easy use. Researchers called the results 'astonishing' and a state-of-the-art leap for biology and medicine.", "body_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计。\n\n英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。\n\nRFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。\n\n该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "url": "https://x.com/i/trending/2112905930044317939", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T16:58:22.000Z"}, {"id": "2112579117904535807", "domain": "科技", "title_en": "Micron Funds New York Minerals Processing for AI Chip Supplies", "title_zh": "美光出资支持纽约关键矿物精炼，保障 AI 芯片原料", "hook_en": "Micron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.", "hook_zh": "美光加大在纽约本土保障 AI 存储芯片关键材料供应的力度，意在削减对海外来源的依赖，以应对需求激增。", "summary_en": "Micron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S. semiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "summary_zh": "美光科技宣布向 Indium Corporation 提供战略性资金，扩大其纽约罗马工厂对铟等关键矿物的精炼，并配套长期供货协议。此举支撑美光约 30 亿美元的美国半导体供应链投资，也回应中国在关键材料生产中的主导地位。尽管对国家安全与 AI 增长属正面一步，当日股价仍因 AI 开支、台湾相关冲击与竞争等担忧下跌约 2%–3%。", "body_en": "Micron Funds New York Minerals Processing for AI Chip Supplies.\n\nMicron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.\n\nMicron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S.\n\nsemiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "body_zh": "美光出资支持纽约关键矿物精炼，保障 AI 芯片原料。\n\n美光加大在纽约本土保障 AI 存储芯片关键材料供应的力度，意在削减对海外来源的依赖，以应对需求激增。\n\n美光科技宣布向 Indium Corporation 提供战略性资金，扩大其纽约罗马工厂对铟等关键矿物的精炼，并配套长期供货协议。\n\n此举支撑美光约 30 亿美元的美国半导体供应链投资，也回应中国在关键材料生产中的主导地位。尽管对国家安全与 AI 增长属正面一步，当日股价仍因 AI 开支、台湾相关冲击与竞争等担忧下跌约 2%–3%。", "url": "https://x.com/i/trending/2112579117904535807", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T16:26:46.000Z"}, {"id": "2112684362596766177", "domain": "科技", "title_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots", "title_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具", "hook_en": "Imagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.", "hook_zh": "一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。", "summary_en": "Viggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video. Dream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "summary_zh": "Viggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。Dream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "body_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots.\n\nImagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.\n\nViggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video.\n\nDream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "body_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具。\n\n一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。\n\nViggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。\n\nDream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "url": "https://x.com/i/trending/2112684362596766177", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T23:23:26.000Z"}, {"id": "2112891431543275870", "domain": "科技", "title_en": "NVIDIA Unveils DSX POD for Rapid AI Factory Deployment", "title_zh": "英伟达 DSX POD：两周内搭起 AI 工厂", "hook_en": "NVIDIA just made building massive AI factories way faster—cutting setup from six months to just 14 days with ready-to-ship containers.", "hook_zh": "过去数月才能建起的巨型 AI 工厂，英伟达新设计宣称最快约 14 天就能交付。", "summary_en": "At GTC Berlin, NVIDIA introduced the DSX POD, a shipping container packed with seven Vera Rubin racks, pre-integrated with cabling, power, and liquid cooling for quick worldwide delivery starting early 2027. CEO Jensen Huang pointed out assembly now takes under five minutes per node—a 24x speedup over before—unlocking billions in revenue by slashing delays on gigawatt-scale projects that cost $50 billion but generate $40 billion yearly. Google Cloud jumped in with A5X instances using Vera Rubin NVL72 systems, aiming for 960,000 GPUs, while partners like Dell and HPE build out the ecosystem to speed AI infrastructure worldwide.", "summary_zh": "在柏林 GTC 上，英伟达发布 DSX POD：把 Vera Rubin AI 工厂做成可由戴尔、HPE、联想等伙伴预装测试的集装箱式模块。在电力、冷却与网络就绪后，部署可压缩到约 14 天，以缓解吉瓦级机房因延期损失的收入。设计还采用闭环液冷，据称可大幅减少用水并降低约 30% 功耗。伙伴计划自 2027 年初起全球交付。", "body_en": "NVIDIA's DSX POD Speeds AI Factories to 14 Days.\n\nImagine spinning up a massive AI factory in just two weeks instead of months. NVIDIA's new design makes that real, easing the rush for builders racing to capture billions in revenue.\n\nAt its GTC conference in Berlin, NVIDIA unveiled the DSX POD, a modular system that packages Vera Rubin AI factories into shippable containers built and tested by partners like Dell, HPE, and Lenovo. These units cut deployment time to as little as 14 days once power, cooling, and networking are ready, addressing delays that cost billions in lost revenue for 1-gigawatt facilities.\n\nThe design also boosts efficiency with closed-loop liquid cooling that slashes water use by up to 100 percent and power needs by 30 percent, helping operators generate output while permanent data centers are built. Partners will deliver the PODs worldwide starting early 2027.", "body_zh": "英伟达 DSX POD：两周内搭起 AI 工厂。\n\n过去数月才能建起的巨型 AI 工厂，英伟达新设计宣称最快约 14 天就能交付。\n\n在柏林 GTC 上，英伟达发布 DSX POD：把 Vera Rubin AI 工厂做成可由戴尔、HPE、联想等伙伴预装测试的集装箱式模块。在电力、冷却与网络就绪后，部署可压缩到约 14 天，以缓解吉瓦级机房因延期损失的收入。\n\n设计还采用闭环液冷，据称可大幅减少用水并降低约 30% 功耗。伙伴计划自 2027 年初起全球交付。", "url": "https://x.com/i/trending/2112891431543275870", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:58:40.000Z"}, {"id": "2112933585816781110", "domain": "商业", "title_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash", "title_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹", "hook_en": "Charles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.", "hook_zh": "Charles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。", "summary_en": "On the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth. Godongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "summary_zh": "在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。Godongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "body_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash.\n\nCharles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.\n\nOn the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth.\n\nGodongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "body_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹。\n\nCharles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。\n\n在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。\n\nGodongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "url": "https://x.com/i/trending/2112933585816781110", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T15:54:19.000Z"}, {"id": "2112796521959985524", "domain": "商业", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z"}, {"id": "2112044241161433358", "domain": "商业", "title_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures", "title_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌", "hook_en": "Japanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.", "hook_zh": "日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。", "summary_en": "Japan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers. A South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "summary_zh": "日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "body_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures.\n\nJapanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.\n\nJapan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers.\n\nA South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "body_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌。\n\n日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。\n\n日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。\n\n韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "url": "https://x.com/i/trending/2112044241161433358", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-20T12:59:35.000Z"}, {"id": "2112431560116826201", "domain": "商业", "title_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms", "title_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论", "hook_en": "Subhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.", "hook_zh": "前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。", "summary_en": "Garg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks. Critics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "summary_zh": "加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。IMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "body_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms.\n\nSubhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.\n\nGarg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks.\n\nCritics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "body_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论。\n\n前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。\n\n加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。\n\nIMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "url": "https://x.com/i/trending/2112431560116826201", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T06:36:16.000Z"}, {"id": "2112771431633502285", "domain": "商业", "title_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21", "title_zh": "节后高开后 Nifty 遭遇抛压", "hook_en": "Nifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.", "hook_zh": "排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。", "summary_en": "After Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478. Analysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "summary_zh": "指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "body_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21.\n\nNifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.\n\nAfter Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478.\n\nAnalysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "body_zh": "节后高开后 Nifty 遭遇抛压。\n\n排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。\n\n指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。\n\n布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "url": "https://x.com/i/trending/2112771431633502285", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T08:16:34.000Z"}, {"id": "2112266057628913774", "domain": "商业", "title_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade", "title_zh": "对冲基金十年最快速度抛售科技股", "hook_en": "Hedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.", "hook_zh": "对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。", "summary_en": "Through October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S. tech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "summary_zh": "截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "body_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade.\n\nHedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.\n\nThrough October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S.\n\ntech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "body_zh": "对冲基金十年最快速度抛售科技股。\n\n对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。\n\n截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。\n\n投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "url": "https://x.com/i/trending/2112266057628913774", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:07:55.000Z"}, {"id": "2112507803138973871", "domain": "商业", "title_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto", "title_zh": "美联储购入 18.27 亿美元国债，股币齐涨", "hook_en": "US stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.", "hook_zh": "美联储买入 18.27 亿美元短期国债并于当日交割后，美股与加密货币周二走高，交易员情绪升温。", "summary_en": "The New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves. Bitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "summary_zh": "纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债标售，10 月 20 日交割，属维持银行准备金的常规二级市场购买。比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称流动性注入「巨大」并利好风险资产。交易员关注 11 月前更多既定购买，但也有人指出多为滚动到期持仓，并非显著扩表。", "body_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto.\n\nUS stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.\n\nThe New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves.\n\nBitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "body_zh": "美联储购入 18.27 亿美元国债，股币齐涨。\n\n美联储买入 18.27 亿美元短期国债并于当日交割后，美股与加密货币周二走高，交易员情绪升温。\n\n纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债标售，10 月 20 日交割，属维持银行准备金的常规二级市场购买。\n\n比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称流动性注入「巨大」并利好风险资产。交易员关注 11 月前更多既定购买，但也有人指出多为滚动到期持仓，并非显著扩表。", "url": "https://x.com/i/trending/2112507803138973871", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:09:54.000Z"}, {"id": "2112795004678676841", "domain": "商业", "title_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister", "title_zh": "印度中小盘暴跌，市场怒火指向财长", "hook_en": "Investors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.", "hook_zh": "2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。", "summary_en": "The Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking. Social media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "summary_zh": "Nifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "body_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister.\n\nInvestors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.\n\nThe Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking.\n\nSocial media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "body_zh": "印度中小盘暴跌，市场怒火指向财长。\n\n2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。\n\nNifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。\n\n小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "url": "https://x.com/i/trending/2112795004678676841", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T13:45:53.000Z"}, {"id": "2112656501483684033", "domain": "商业", "title_en": "United Airlines Hits Record Revenue but Misses Earnings on High Fuel Costs", "title_zh": "美联航营收创新高，油价飙升拖累每股收益", "hook_en": "United Airlines flew a record number of passengers and smashed revenue highs this quarter, but soaring fuel prices clipped their earnings wings.", "hook_zh": "本季度美联航客运与营收均刷新纪录，但燃油成本高企削弱了盈利表现。", "summary_en": "For the three months ended September 30, United reported $17.9 billion in operating revenue, up 17.4% from last year, with passenger revenue rising 17.6% to $16.24 billion and a record 49.5 million customers carried. Adjusted earnings per share came in at $2.54, slightly below Wall Street's $2.57 to $2.59 expectations, as fuel costs surged 61.6% to $4.84 billion at $3.90 per gallon. CEO Scott Kirby praised employees' resilience and highlighted Starlink Wi-Fi now on over 640 aircraft, while Q4 guidance forecasts over 20% revenue growth but adjusted EPS of just $0.50 to $1.50 amid $4.80 per gallon fuel—far under analyst hopes—sending shares down 2% to 4% after hours.", "summary_zh": "截至 9 月 30 日的三个月，美联航实现营业收入 179 亿美元，同比增 17.4%；客运收入 162.4 亿美元，承运旅客创纪录达 4950 万人次。调整后每股收益 2.54 美元，略低于华尔街 2.57–2.59 美元预期；燃油成本飙升 61.6% 至 48.4 亿美元，折合每加仑 3.90 美元。CEO 柯比肯定员工表现，并称逾 640 架飞机已开通星链 Wi-Fi。四季度指引预计营收增长超 20%，但调整后每股收益仅 0.50–1.50 美元，盘后股价下跌约 2%–4%。", "body_en": "United Airlines Hits Record Revenue but Misses Earnings on High Fuel Costs.\n\nUnited Airlines flew a record number of passengers and smashed revenue highs this quarter, but soaring fuel prices clipped their earnings wings.\n\nFor the three months ended September 30, United reported $17.9 billion in operating revenue, up 17.4% from last year, with passenger revenue rising 17.6% to $16.24 billion and a record 49.5 million customers carried.\n\nAdjusted earnings per share came in at $2.54, slightly below Wall Street's $2.57 to $2.59 expectations, as fuel costs surged 61.6% to $4.84 billion at $3.90 per gallon. CEO Scott Kirby praised employees' resilience and highlighted Starlink Wi-Fi now on over 640 aircraft, while Q4 guidance forecasts over 20% revenue growth but adjusted EPS of just $0.50 to $1.50 amid $4.80 per gallon fuel—far under analyst hopes—sending shares down 2% to 4% after hours.", "body_zh": "美联航营收创新高，油价飙升拖累每股收益。\n\n本季度美联航客运与营收均刷新纪录，但燃油成本高企削弱了盈利表现。\n\n截至 9 月 30 日的三个月，美联航实现营业收入 179 亿美元，同比增 17.4%；客运收入 162.4 亿美元，承运旅客创纪录达 4950 万人次。调整后每股收益 2.54 美元，略低于华尔街 2.57–2.59 美元预期；燃油成本飙升 61.6% 至 48.4 亿美元，折合每加仑 3.90 美元。\n\nCEO 柯比肯定员工表现，并称逾 640 架飞机已开通星链 Wi-Fi。四季度指引预计营收增长超 20%，但调整后每股收益仅 0.50–1.50 美元，盘后股价下跌约 2%–4%。", "url": "https://x.com/i/trending/2112656501483684033", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T01:10:41.000Z"}, {"id": "2112637290933789168", "domain": "商业", "title_en": "Netflix Stock Plunges on Weak Ad Guidance and YouTube Competition", "title_zh": "奈飞三季度营收达标但指引逊色，股价盘后下跌", "hook_en": "Netflix's latest earnings hit Wall Street like a plot twist nobody saw coming, with shares dropping over 5% and erasing massive market value overnight.", "hook_zh": "营收达到目标，前瞻指引不及预期，盘后股价跌约 5%–6%。", "summary_en": "The company reported third-quarter revenue of $12.87 billion in line with expectations and earnings per share of 87 cents that beat estimates, alongside record 34.6% operating margins and 44% net income growth to $3.66 billion. But investors sold off after Netflix cut its full-year ad revenue forecast to $2.7 billion from near $3 billion, trimmed 2026 revenue guidance to $51.1 billion, and signaled softer Q4 results. Amid YouTube's rising U.S. viewing share near 14% compared to Netflix's flat 8%, one investor noted daily YouTube watches versus a dormant Netflix subscription, fueling concerns over engagement and competition as shares hit 2024 lows around $65.", "summary_zh": "奈飞营收 128.7 亿美元，同比增长 12%，为三年来最慢；每股收益 0.87 美元超预期，营业利润率达 34.6%。四季度营收 134.4 亿美元、EPS 0.67 美元的展望令华尔街失望，2026 年广告收入目标亦下调至 27 亿美元。叠加裁员约 1000 人及 YouTube 抢占美国电视份额，投资者对原创内容与广告扩张看法分化。", "body_en": "Netflix Stock Plunges on Weak Ad Guidance and YouTube Competition.\n\nNetflix's latest earnings hit Wall Street like a plot twist nobody saw coming, with shares dropping over 5% and erasing massive market value overnight.\n\nThe company reported third-quarter revenue of $12.87 billion in line with expectations and earnings per share of 87 cents that beat estimates, alongside record 34.6% operating margins and 44% net income growth to $3.66 billion. But investors sold off after Netflix cut its full-year ad revenue forecast to $2.7 billion from near $3 billion, trimmed 2026 revenue guidance to $51.1 billion, and signaled softer Q4 results.\n\nAmid YouTube's rising U.S. viewing share near 14% compared to Netflix's flat 8%, one investor noted daily YouTube watches versus a dormant Netflix subscription, fueling concerns over engagement and competition as shares hit 2024 lows around $65.", "body_zh": "奈飞三季度营收达标但指引逊色，股价盘后下跌。\n\n营收达到目标，前瞻指引不及预期，盘后股价跌约 5%–6%。\n\n奈飞营收 128.7 亿美元，同比增长 12%，为三年来最慢；每股收益 0.87 美元超预期，营业利润率达 34.6%。\n\n四季度营收 134.4 亿美元、EPS 0.67 美元的展望令华尔街失望，2026 年广告收入目标亦下调至 27 亿美元。叠加裁员约 1000 人及 YouTube 抢占美国电视份额，投资者对原创内容与广告扩张看法分化。", "url": "https://x.com/i/trending/2112637290933789168", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T18:24:11.000Z"}, {"id": "2112501506846916810", "domain": "商业", "title_en": "GM Shares Drop After Earnings Beat but Lowered 2026 Profit Outlook", "title_zh": "通用汽车财报超预期却下调 2026 盈利展望，股价大跌", "hook_en": "General Motors posted a strong quarter with revenue topping estimates, yet shares tumbled as investors zeroed in on a narrower full-year profit forecast amid rising costs.", "hook_zh": "通用汽车本季营收超预期，但投资者聚焦全年盈利展望收窄与成本上升，股价应声回落。", "summary_en": "GM reported third-quarter revenue of $50.02 billion, beating expectations of $48.7 billion, with adjusted EPS at $3.70 versus $3.63 anticipated and adjusted EBIT of $4.11 billion. Despite this and a new $20 billion stock buyback plus a $0.18 quarterly dividend, the company cut its 2026 outlook to adjusted EPS of $12.75-$13.75, below prior consensus, and adjusted EBIT of $14.5-$15.5 billion due to higher commodity and logistics costs. Strong North American truck sales boosted automotive free cash flow 40% to $5.9 billion, but critics questioned buybacks over EV and autonomy investments as shares fell as much as 8% in premarket trading to around $77.", "summary_zh": "通用汽车公布三季度营收 500.2 亿美元，高于预期的 487 亿美元；调整后每股收益 3.70 美元（预期 3.63 美元），调整后息税前利润 41.1 亿美元。尽管另宣布 200 亿美元股票回购计划及每股 0.18 美元季度股息，公司仍因大宗商品与物流成本上升，将 2026 年调整后每股收益展望下调至 12.75–13.75 美元、调整后息税前利润 145–155 亿美元，低于此前共识。北美卡车销售强劲推动汽车业务自由现金流增 40% 至 59 亿美元，但批评者质疑回购优先于电动车与自动驾驶投入；盘前股价一度跌约 8% 至约 77 美元。", "body_en": "GM Shares Drop After Earnings Beat but Lowered 2026 Profit Outlook.\n\nGeneral Motors posted a strong quarter with revenue topping estimates, yet shares tumbled as investors zeroed in on a narrower full-year profit forecast amid rising costs.\n\nGM reported third-quarter revenue of $50.02 billion, beating expectations of $48.7 billion, with adjusted EPS at $3.70 versus $3.63 anticipated and adjusted EBIT of $4.11 billion.\n\nDespite this and a new $20 billion stock buyback plus a $0.18 quarterly dividend, the company cut its 2026 outlook to adjusted EPS of $12.75-$13.75, below prior consensus, and adjusted EBIT of $14.5-$15.5 billion due to higher commodity and logistics costs. Strong North American truck sales boosted automotive free cash flow 40% to $5.9 billion, but critics questioned buybacks over EV and autonomy investments as shares fell as much as 8% in premarket trading to around $77.", "body_zh": "通用汽车财报超预期却下调 2026 盈利展望，股价大跌。\n\n通用汽车本季营收超预期，但投资者聚焦全年盈利展望收窄与成本上升，股价应声回落。\n\n通用汽车公布三季度营收 500.2 亿美元，高于预期的 487 亿美元；调整后每股收益 3.70 美元（预期 3.63 美元），调整后息税前利润 41.1 亿美元。\n\n尽管另宣布 200 亿美元股票回购计划及每股 0.18 美元季度股息，公司仍因大宗商品与物流成本上升，将 2026 年调整后每股收益展望下调至 12.75–13.75 美元、调整后息税前利润 145–155 亿美元，低于此前共识。北美卡车销售强劲推动汽车业务自由现金流增 40% 至 59 亿美元，但批评者质疑回购优先于电动车与自动驾驶投入；盘前股价一度跌约 8% 至约 77 美元。", "url": "https://x.com/i/trending/2112501506846916810", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-20T20:55:03.000Z"}, {"id": "2112908300035776814", "domain": "商业", "title_en": "Micron and Nvidia Drive 36% of S&P 500 Earnings Growth", "title_zh": "美光与英伟达贡献标普 500 盈利增长的 36%", "hook_en": "Two tech giants are carrying the S&P 500's earnings on their shoulders, with the rest of the market trailing far behind.", "hook_zh": "两家科技巨头扛起标普 500 盈利增长大梁，其余公司远远落后。", "summary_en": "For Q3 2026, Micron Technology and Nvidia are projected to fuel 36% of the index's 27% year-over-year earnings growth, contributing 5.2 and 4.6 percentage points respectively. The top 15 stocks now hold 46.7% of the S&P 500's market value—far exceeding dot-com bubble levels—with Nvidia, Apple, Alphabet, and Microsoft alone making up over a quarter. Without the top 10 contributors, earnings would shrink 11% year over year, highlighting heavy reliance on AI-linked firms amid surging memory demand from training, inference, and emerging applications like robotaxis. Micron's stock has surged over 340% in the past year as investors eye its AI roadmap.", "summary_zh": "预计 2026 年三季度，美光科技与英伟达将贡献该指数同比 27% 盈利增长中的 36%，分别贡献 5.2 与 4.6 个百分点。市值最大的 15 只股票已占标普 500 总市值的 46.7%——远超互联网泡沫时期水平——仅英伟达、苹果、Alphabet 与微软就占逾四分之一。若剔除前十大贡献者，盈利将同比萎缩 11%，凸显对 AI 相关公司的高度依赖，以及训练、推理与 Robotaxi 等新兴应用带动的存储需求。过去一年美光股价已飙升逾 340%，投资者押注其 AI 路线图。", "body_en": "Micron and Nvidia Drive 36% of S&P 500 Earnings Growth.\n\nTwo tech giants are carrying the S&P 500's earnings on their shoulders, with the rest of the market trailing far behind.\n\nFor Q3 2026, Micron Technology and Nvidia are projected to fuel 36% of the index's 27% year-over-year earnings growth, contributing 5.2 and 4.6 percentage points respectively. The top 15 stocks now hold 46.7% of the S&P 500's market value—far exceeding dot-com bubble levels—with Nvidia, Apple, Alphabet, and Microsoft alone making up over a quarter.\n\nWithout the top 10 contributors, earnings would shrink 11% year over year, highlighting heavy reliance on AI-linked firms amid surging memory demand from training, inference, and emerging applications like robotaxis. Micron's stock has surged over 340% in the past year as investors eye its AI roadmap.", "body_zh": "美光与英伟达贡献标普 500 盈利增长的 36%。\n\n两家科技巨头扛起标普 500 盈利增长大梁，其余公司远远落后。\n\n预计 2026 年三季度，美光科技与英伟达将贡献该指数同比 27% 盈利增长中的 36%，分别贡献 5.2 与 4.6 个百分点。市值最大的 15 只股票已占标普 500 总市值的 46.7%——远超互联网泡沫时期水平——仅英伟达、苹果、Alphabet 与微软就占逾四分之一。\n\n若剔除前十大贡献者，盈利将同比萎缩 11%，凸显对 AI 相关公司的高度依赖，以及训练、推理与 Robotaxi 等新兴应用带动的存储需求。过去一年美光股价已飙升逾 340%，投资者押注其 AI 路线图。", "url": "https://x.com/i/trending/2112908300035776814", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T16:44:49.000Z"}, {"id": "2112620331987062878", "domain": "商业", "title_en": "Investors Surge Protection Purchases on AI Tech Debt", "title_zh": "投资者创纪录买入 CDS，对冲 AI 企业债务风险", "hook_en": "Wall Street traders are snapping up insurance against defaults on massive AI loans, with volumes hitting records as costs climb.", "hook_zh": "AI 公司为数据中心与芯片大举举债之际，投资者正以前所未有的规模买入信用违约互换，防范违约。", "summary_en": "Trading in credit default swaps tied to Nvidia, Meta, Amazon, Alphabet, Microsoft, and others jumped over fourfold to $9 billion weekly in September, fueled by $466 billion in 2026 AI bond sales for data centers and chips. Spreads reached records like Meta's 108 basis points and Nvidia's 101, while riskier names like CoreWeave hit 1,090 amid leverage worries. A report warns of subprime-like risks to pension funds and retirement plans, though analysts point to strong earnings as a counterbalance.", "summary_zh": "与 AI 相关企业在 2026 年累计发行约 4660 亿美元债务，超过去年四倍，支撑大规模数据中心与芯片投资。9 月针对甲骨文、英伟达、Meta 等债券的 CDS 周交易额达 90 亿美元，保护成本飙升——Meta 约 108 个基点、英伟达约 101，CoreWeave 则超过 1000、进入困境区间。分析人士如穆罕默德·埃里安对借贷潮表示不安，亦有报告警示再包装债务卖给养老金等资金或带有类似次贷的风险；也有观点以强劲盈利增长作为对冲论据。", "body_en": "Investors Buy Record CDS to Hedge AI Company Debt Risks.\n\nAs AI firms borrow billions for data centers and chips, investors are snapping up credit default swaps at unprecedented levels to guard against defaults.\n\nAI-linked companies issued $466 billion in debt through 2026, more than quadrupling last year's pace, fueling massive data center and chip investments.\n\nWeekly CDS trading on bonds from Oracle, Nvidia, Meta, and others hit $9 billion in September, with protection costs soaring—Meta at 108 basis points, Nvidia at 101, and CoreWeave over 1,000 in distressed levels. Analysts like Mohamed El-Erian flag unease over the borrowing surge, while reports warn of subprime-like risks in repackaged debt sold to pensions, though some point to strong earnings growth as a counterbalance.", "body_zh": "投资者创纪录买入 CDS，对冲 AI 企业债务风险。\n\nAI 公司为数据中心与芯片大举举债之际，投资者正以前所未有的规模买入信用违约互换，防范违约。\n\n与 AI 相关企业在 2026 年累计发行约 4660 亿美元债务，超过去年四倍，支撑大规模数据中心与芯片投资。\n\n9 月针对甲骨文、英伟达、Meta 等债券的 CDS 周交易额达 90 亿美元，保护成本飙升——Meta 约 108 个基点、英伟达约 101，CoreWeave 则超过 1000、进入困境区间。分析人士如穆罕默德·埃里安对借贷潮表示不安，亦有报告警示再包装债务卖给养老金等资金或带有类似次贷的风险；也有观点以强劲盈利增长作为对冲论据。", "url": "https://x.com/i/trending/2112620331987062878", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T16:34:34.000Z"}, {"id": "2112486884211650655", "domain": "中国", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province.\n\nThe event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112895365657567737", "domain": "中国", "title_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike", "title_zh": "美光与台中厂达成劳资协议，罢工风险缓解", "hook_en": "Workers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.", "hook_zh": "美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。", "summary_en": "The deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days. Unions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "summary_zh": "台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "body_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike.\n\nWorkers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.\n\nThe deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days.\n\nUnions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "body_zh": "美光与台中厂达成劳资协议，罢工风险缓解。\n\n美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。\n\n台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。\n\n双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "url": "https://x.com/i/trending/2112895365657567737", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T13:20:26.000Z"}, {"id": "2112572571275370804", "domain": "中国", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.\n\nJapan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z"}, {"id": "2112290595213554074", "domain": "中国", "title_en": "Micheál Martin Defends Triple Lock Reform Amid Neutrality Clash", "title_zh": "爱尔兰辩论改革维和「三重锁」部署机制", "hook_en": "In a tense Dáil exchange, Taoiseach Micheál Martin shot back at critics with a firm 'How dare you lecture me about Irish neutrality?' as debates heated up over peacekeeping changes.", "hook_zh": "总理马丁在议会回击：「你凭什么教训我爱尔兰中立？俄罗斯不该对爱尔兰参与维和拥有否决权。」现场气氛火药味十足。", "summary_en": "The Irish government is pushing to reform the Triple Lock mechanism, which currently requires UN Security Council approval for deploying more than 12 troops overseas, by dropping that UN veto to avoid blocks from nations like Russia or China. Martin and Fianna Fáil argue this preserves Ireland's peacekeeping role without foreign dictation, a pledge from their 2024 election campaign now in the Programme for Government. Opponents, including senators and TDs waving 'Save Neutrality' signs, warn it erodes neutrality and risks pulling troops into non-UN conflicts like a potential EU mission in Lebanon, calling for a referendum instead. The bill advances this week despite the row.", "summary_zh": "爱尔兰政府推进《国防（修正）法案》，拟废除「三重锁」中的联合国授权要求——目前向海外部署超过 12 名国防军须经政府批准、议会表决与联合国背书。马丁等支持者称可防止俄中等大国否决，保障如黎巴嫩维和等任务，尤其在 2014 年以来联合国僵局下。反对派包括玛丽·卢·麦克唐纳与 Peadar Tóibín 指责此举偏离维和、倒向欧盟军事行动，要求公投；议员挥舞「保卫中立」标语，民间亦有抗议。", "body_en": "Ireland Debates Reforming Triple Lock on Peacekeeping Deployments.\n\nTaoiseach Micheál Martin fired back in the Dáil: 'How dare you lecture me about Irish neutrality? Russia should not have a veto on Irish participation in peacekeeping.' The exchange captured the chamber's raw tension over neutrality's future.\n\nThe Irish government is advancing the Defence (Amendment) Bill to scrap the UN mandate requirement in the Triple Lock, which currently needs government approval, a Dáil vote, and UN backing for deploying over 12 Defence Forces members abroad.\n\nProponents like Martin argue it prevents vetoes by powers like Russia or China, safeguarding missions such as Ireland's in Lebanon amid UN gridlock since 2014. Opposition leaders, including Mary Lou McDonald and Peadar Tóibín, decry it as a drift from peacekeeping to EU-aligned military action and demand a referendum, with TDs waving 'Save Neutrality' signs amid public protests.", "body_zh": "爱尔兰辩论改革维和「三重锁」部署机制。\n\n总理马丁在议会回击：「你凭什么教训我爱尔兰中立？俄罗斯不该对爱尔兰参与维和拥有否决权。」现场气氛火药味十足。\n\n爱尔兰政府推进《国防（修正）法案》，拟废除「三重锁」中的联合国授权要求——目前向海外部署超过 12 名国防军须经政府批准、议会表决与联合国背书。\n\n马丁等支持者称可防止俄中等大国否决，保障如黎巴嫩维和等任务，尤其在 2014 年以来联合国僵局下。反对派包括玛丽·卢·麦克唐纳与 Peadar Tóibín 指责此举偏离维和、倒向欧盟军事行动，要求公投；议员挥舞「保卫中立」标语，民间亦有抗议。", "url": "https://x.com/i/trending/2112290595213554074", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T18:24:19.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Billboards with Scientists' Portraits in Major Cities", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Rocket scientist Qian Xuesen's giant portrait now greets shoppers in a Heze mall, replacing flashy ads with faces of national heroes.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "Since August 2026, cities like Heze, Zhengzhou, and Chongqing have filled public screens in malls, metros, and plazas with portraits of scientists such as Qian Xuesen, Yuan Longping, and Tu Youyou, complete with notes on their breakthroughs in rockets, rice, and malaria drugs. Local venues made these voluntary changes, often timed for holidays to highlight achievements in science and defense. The shift has sparked online talk about honoring innovators over celebrities and what public spaces say about a society's values.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T10:44:04.000Z"}, {"id": "2112161836116132305", "domain": "中国", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z"}, {"id": "2112437946263474495", "domain": "中国", "title_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal", "title_zh": "中国对美舰接近争议南沙礁盘实施跟踪监视", "hook_en": "Early Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.", "hook_zh": "周二早间，一艘美国濒海战斗舰驶入中国所称仙宾礁附近海域，北京随即派出力量实施抵近监视。", "summary_en": "China's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "summary_zh": "中国人民解放军海军指控「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾方面反驳称该舰停留在国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。此事发生在同礁附近不久前的船只碰撞之后，也正值多国在南海提出重叠领土主张之际。", "body_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal.\n\nEarly Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability.\n\nThe Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "body_zh": "中国对美舰接近争议南沙礁盘实施跟踪监视。\n\n周二早间，一艘美国濒海战斗舰驶入中国所称仙宾礁附近海域，北京随即派出力量实施抵近监视。\n\n中国人民解放军海军指控「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。\n\n菲律宾方面反驳称该舰停留在国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。此事发生在同礁附近不久前的船只碰撞之后，也正值多国在南海提出重叠领土主张之际。", "url": "https://x.com/i/trending/2112437946263474495", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T15:35:04.000Z"}, {"id": "2112405151768100963", "domain": "中国", "title_en": "Philippine Senators Push to Expel Chinese Ambassador Over Sea Threat", "title_zh": "菲律宾参议员推动驱逐中国大使", "hook_en": "Chinese Ambassador Jing Quan's words hung heavy: China could 'easily win' with force in the West Philippine Sea, though it prefers peace. Philippine senators fired back, demanding he be sent home.", "hook_zh": "中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。", "summary_en": "Senators Risa Hontiveros and Erwin Tulfo filed resolutions urging President Marcos to declare Ambassador Jing persona non grata after his remarks, seen as a veiled threat amid China's vessel harassment and illegal fishing in Philippine waters. The Department of Foreign Affairs summoned Jing to protest, while Senator Kiko Pangilinan sharply challenged Marcos to act decisively. The Chinese Embassy hit back by listing critical lawmakers online, but Malacañang favors diplomatic channels over expulsion to avoid escalation.", "summary_zh": "参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "body_en": "Chinese Ambassador Jing Quan boasted that China could 'easily win' any conflict with the Philippines, igniting calls from senators to send him packing.\n\nSenators Risa Hontiveros and Erwin Tulfo filed resolutions on October 20 and the day before, urging President Marcos to declare Ambassador Jing persona non grata or request his recall from Beijing. The remarks responded to Defense Secretary Gilberto Teodoro Jr.\n\nlabeling China a regional troublemaker, prompting the Chinese Embassy's taunting social media posts like 'You are now on the list' targeting critics. The Department of Foreign Affairs summoned Jing on October 19, calling his words a provocative threat amid ongoing West Philippine Sea tensions, though Marcos prefers diplomatic talks over expulsion.", "body_zh": "菲律宾参议员推动驱逐中国大使。中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。\n\n参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。\n\n外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。\n\n以上内容根据公开讨论与报道梳理，详情可在 X 原文页继续跟踪进展。", "url": "https://x.com/i/trending/2112405151768100963", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T10:24:16.000Z"}, {"id": "2112595600831033552", "domain": "中国", "title_en": "Micron Shares Slide Amid Chart Warnings and Taiwan Strike", "title_zh": "美光股价回落：图表示警叠加台湾一日罢工", "hook_en": "Micron's stock has tumbled from over $1,250 in June to around $880-$910, leaving traders glued to key support levels like $877-$880.", "hook_zh": "美光股价自 6 月逾 1250 美元跌至约 880–910 美元，交易者紧盯 877–880 美元等关键支撑。", "summary_en": "The memory chipmaker faces a volatile pullback, with analysts spotting bear flag breakdowns on charts and potential drops toward $725 if support fails. Bulls watch for a rebound above $920-$930, backed by strong Q4 results showing massive revenue growth from AI-driven high-bandwidth memory demand and a new $35.16 billion buyback starting December 9. Short-term worries include a one-day strike by Taiwan's Taoyuan union on October 22 over bonuses, adding uncertainty at key manufacturing sites.", "summary_zh": "这家存储芯片商正经历剧烈回调，分析师指出图表上出现熊旗破位迹象，若支撑失守或下看约 725 美元。多头则等待重返 920–930 美元上方，依据包括第四季度强劲业绩——AI 驱动高带宽内存需求带动营收大增——以及自 12 月 9 日起总额约 351.6 亿美元的新回购。短期扰动还包括台湾桃园工会计划 10 月 22 日就奖金问题举行一日罢工，给关键制造节点增添不确定性。", "body_en": "Micron Shares Slide Amid Chart Warnings and Taiwan Strike.\n\nMicron's stock has tumbled from over $1,250 in June to around $880-$910, leaving traders glued to key support levels like $877-$880.\n\nThe memory chipmaker faces a volatile pullback, with analysts spotting bear flag breakdowns on charts and potential drops toward $725 if support fails.\n\nBulls watch for a rebound above $920-$930, backed by strong Q4 results showing massive revenue growth from AI-driven high-bandwidth memory demand and a new $35.16 billion buyback starting December 9. Short-term worries include a one-day strike by Taiwan's Taoyuan union on October 22 over bonuses, adding uncertainty at key manufacturing sites.", "body_zh": "美光股价回落：图表示警叠加台湾一日罢工。\n\n美光股价自 6 月逾 1250 美元跌至约 880–910 美元，交易者紧盯 877–880 美元等关键支撑。\n\n这家存储芯片商正经历剧烈回调，分析师指出图表上出现熊旗破位迹象，若支撑失守或下看约 725 美元。\n\n多头则等待重返 920–930 美元上方，依据包括第四季度强劲业绩——AI 驱动高带宽内存需求带动营收大增——以及自 12 月 9 日起总额约 351.6 亿美元的新回购。短期扰动还包括台湾桃园工会计划 10 月 22 日就奖金问题举行一日罢工，给关键制造节点增添不确定性。", "url": "https://x.com/i/trending/2112595600831033552", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-20T17:33:15.000Z"}, {"id": "2112653366941950015", "domain": "中国", "title_en": "China's 'Fake Commuting' Hides Unemployment from Families", "title_zh": "中国出现“假装上班”：失业者用作息瞒住家人", "hook_en": "A jobless worker waves goodbye each morning, 'Bye, I'm off to work,' then heads straight to the bar. This daily pretense is spreading amid China's tough job market.", "hook_zh": "有人每天挥手说“我去上班了”，却径直去酒吧——在就业承压背景下，这类掩饰正被更多讨论。", "summary_en": "Unemployed people in China are leaving home on work-like schedules to keep families from knowing they're jobless, driven by a weak hiring environment, property crisis, automation, and AI adoption. Social platforms buzz with tips on filling the day in cafes, parks, or libraries, echoing the shame in the 2008 Japanese film Tokyo Sonata and similar habits elsewhere. The trend underscores cultural stigma around unemployment and efforts to preserve family harmony despite economic pressures.", "summary_zh": "部分失业者按上班时间出门，以免家人知晓，背后是招聘偏弱、房地产调整、自动化与 AI 应用等因素。社交平台流传在咖啡馆、公园、图书馆消磨白天的经验，令人联想到日本电影《东京奏鸣曲》中的耻辱感。现象折射失业污名与家庭体面压力，也引发对就业与社会保障的讨论。", "body_en": "China's 'Fake Commuting' Hides Unemployment from Families.\n\nA jobless worker waves goodbye each morning, 'Bye, I'm off to work,' then heads straight to the bar. This daily pretense is spreading amid China's tough job market.\n\nUnemployed people in China are leaving home on work-like schedules to keep families from knowing they're jobless, driven by a weak hiring environment, property crisis, automation, and AI adoption.\n\nSocial platforms buzz with tips on filling the day in cafes, parks, or libraries, echoing the shame in the 2008 Japanese film Tokyo Sonata and similar habits elsewhere. The trend underscores cultural stigma around unemployment and efforts to preserve family harmony despite economic pressures.", "body_zh": "中国出现“假装上班”：失业者用作息瞒住家人。\n\n有人每天挥手说“我去上班了”，却径直去酒吧——在就业承压背景下，这类掩饰正被更多讨论。\n\n部分失业者按上班时间出门，以免家人知晓，背后是招聘偏弱、房地产调整、自动化与 AI 应用等因素。\n\n社交平台流传在咖啡馆、公园、图书馆消磨白天的经验，令人联想到日本电影《东京奏鸣曲》中的耻辱感。现象折射失业污名与家庭体面压力，也引发对就业与社会保障的讨论。", "url": "https://x.com/i/trending/2112653366941950015", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T21:21:21.000Z"}, {"id": "2112529713906200727", "domain": "中国", "title_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions", "title_zh": "林肯郡市长与台湾台南签署伙伴协议引权限争议", "hook_en": "Dame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.", "hook_zh": "这位市长在视频连线中高调宣布与台南达成协议，网友很快指出市长无权签署国际条约。", "summary_en": "Greater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture. Critics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "summary_zh": "大林肯郡市长分享与台南签署“里程碑贸易协议”的画面，强调农业、科技与文化机会。包括前议会领袖在内的批评者称其越权，澄清实为姐妹城市式地方交流。台湾媒体确认此为英台此类联系的首例，舆论呼吁措辞准确，避免被误解为正式贸易协定。", "body_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions.\n\nDame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.\n\nGreater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture.\n\nCritics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "body_zh": "林肯郡市长与台湾台南签署伙伴协议引权限争议。\n\n这位市长在视频连线中高调宣布与台南达成协议，网友很快指出市长无权签署国际条约。\n\n大林肯郡市长分享与台南签署“里程碑贸易协议”的画面，强调农业、科技与文化机会。\n\n包括前议会领袖在内的批评者称其越权，澄清实为姐妹城市式地方交流。台湾媒体确认此为英台此类联系的首例，舆论呼吁措辞准确，避免被误解为正式贸易协定。", "url": "https://x.com/i/trending/2112529713906200727", "category": "News", "topics": ["News"], "updated_at": "2026-10-20T13:07:49.000Z"}, {"id": "2112426906595524740", "domain": "中国", "title_en": "JoongDunk Fan Meeting Sells Out in Hong Kong Amid Duo Split", "title_zh": "JoongDunk 香港粉丝见面会售罄，恰逢搭档拆伙消息", "hook_en": "Fans grabbed every ticket for JoongDunk's December 5 Hong Kong fan meeting, turning it into a sell-out just days after their agency announced the end of their on-screen pairing.", "hook_zh": "经纪公司刚宣布两人结束荧幕搭档，12 月 5 日香港见面会门票却被粉丝抢光。", "summary_en": "Thai actors Joong Archen Aydin and Dunk Natachai Boonprasert, beloved as JoongDunk, will appear together one last time with their character Jaidee at Nina Hotel Tsuen Wan West. GMMTV announced on October 19 that the pair mutually agreed to pursue separate careers, but this event and prior schedules remain on track. Supporters from multiple countries snapped up tickets and add-ons, sharing emotional tributes like sketches and messages of endless love, while warning against unofficial sellers. The rapid sell-out underscores their lasting bond with fans, who mix joy over the gathering with hopes for cherished memories.", "summary_zh": "泰国演员 Joong 与 Dunk（组合 JoongDunk）将携角色 Jaidee 在荃湾西如心酒店举行见面会。GMMTV 10 月 19 日称双方同意各自发展，但本场与既定行程照常。多国粉丝抢票并分享手绘与留言，也提醒提防黄牛。迅速售罄显示粉丝黏性仍在，喜悦与不舍交织。", "body_en": "JoongDunk Fan Meeting Sells Out in Hong Kong Amid Duo Split.\n\nFans grabbed every ticket for JoongDunk's December 5 Hong Kong fan meeting, turning it into a sell-out just days after their agency announced the end of their on-screen pairing.\n\nThai actors Joong Archen Aydin and Dunk Natachai Boonprasert, beloved as JoongDunk, will appear together one last time with their character Jaidee at Nina Hotel Tsuen Wan West. GMMTV announced on October 19 that the pair mutually agreed to pursue separate careers, but this event and prior schedules remain on track.\n\nSupporters from multiple countries snapped up tickets and add-ons, sharing emotional tributes like sketches and messages of endless love, while warning against unofficial sellers. The rapid sell-out underscores their lasting bond with fans, who mix joy over the gathering with hopes for cherished memories.", "body_zh": "JoongDunk 香港粉丝见面会售罄，恰逢搭档拆伙消息。\n\n经纪公司刚宣布两人结束荧幕搭档，12 月 5 日香港见面会门票却被粉丝抢光。\n\n泰国演员 Joong 与 Dunk（组合 JoongDunk）将携角色 Jaidee 在荃湾西如心酒店举行见面会。GMMTV 10 月 19 日称双方同意各自发展，但本场与既定行程照常。\n\n多国粉丝抢票并分享手绘与留言，也提醒提防黄牛。迅速售罄显示粉丝黏性仍在，喜悦与不舍交织。", "url": "https://x.com/i/trending/2112426906595524740", "category": "Entertainment", "topics": ["Concerts"], "updated_at": "2026-10-21T11:16:28.000Z"}, {"id": "2112807301782638724", "domain": "中国", "title_en": "Kim Hyeyoon Named Taiwan Tourism Ambassador for 2026-2027", "title_zh": "金惠允出任台湾观光大使（2026–2027）", "hook_en": "Kim Hyeyoon stepped out in a crisp white pantsuit, flashing smiles and holding her official certificate as fans snapped photos at the Seoul launch.", "hook_zh": "金惠允身着利落白西装亮相首尔发布会，手持证书微笑，粉丝围拍留念。", "summary_en": "South Korean actress Kim Hyeyoon was appointed promotional ambassador for Taiwan Tourism at a Seoul press conference, where new campaign videos debuted under the slogan 'Everyone, Anytime, Taiwan Delights.' The clips show her enjoying Tainan food streets with her brother, Sun Moon Lake with family, solo time in Kaohsiung, and beach fun with friends, highlighting Taiwan's charms for any traveler or season. Organizers picked her for her bright image and wide appeal, boosted by her popularity from *Lovely Runner* and a 2024 Taiwan fan meeting. She hopes the videos inspire people to plan trips that fit their style.", "summary_zh": "韩国演员金惠允在首尔记者会上获聘台湾观光推广大使，同步亮相「Everyone, Anytime, Taiwan Delights」新宣传片。片段呈现她与兄长逛台南小吃、与家人游日月潭、在高雄独处，以及与友人海边玩乐，强调台湾适合各类旅人与季节。主办方看中其明朗形象与《Lovely Runner》等作品带来的人气，以及 2024 年台湾粉丝见面会的号召力。她希望影片能启发观众规划符合自己风格的行程。", "body_en": "Kim Hyeyoon Named Taiwan Tourism Ambassador for 2026-2027.\n\nKim Hyeyoon stepped out in a crisp white pantsuit, flashing smiles and holding her official certificate as fans snapped photos at the Seoul launch.\n\nSouth Korean actress Kim Hyeyoon was appointed promotional ambassador for Taiwan Tourism at a Seoul press conference, where new campaign videos debuted under the slogan 'Everyone, Anytime, Taiwan Delights.' The clips show her enjoying Tainan food streets with her brother, Sun Moon Lake with family, solo time in Kaohsiung, and beach fun with friends, highlighting Taiwan's charms for any traveler or season.\n\nOrganizers picked her for her bright image and wide appeal, boosted by her popularity from *Lovely Runner* and a 2024 Taiwan fan meeting. She hopes the videos inspire people to plan trips that fit their style.", "body_zh": "金惠允出任台湾观光大使（2026–2027）。\n\n金惠允身着利落白西装亮相首尔发布会，手持证书微笑，粉丝围拍留念。\n\n韩国演员金惠允在首尔记者会上获聘台湾观光推广大使，同步亮相「Everyone, Anytime, Taiwan Delights」新宣传片。片段呈现她与兄长逛台南小吃、与家人游日月潭、在高雄独处，以及与友人海边玩乐，强调台湾适合各类旅人与季节。\n\n主办方看中其明朗形象与《Lovely Runner》等作品带来的人气，以及 2024 年台湾粉丝见面会的号召力。她希望影片能启发观众规划符合自己风格的行程。", "url": "https://x.com/i/trending/2112807301782638724", "category": "Entertainment", "topics": ["Travel"], "updated_at": "2026-10-21T12:40:57.000Z"}, {"id": "2112296384745631848", "domain": "国际", "title_en": "France Protests Spark Debate on Russian Interference Claims", "title_zh": "法国抗议潮引发「俄方干涉」说法之争", "hook_en": "Hundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.", "hook_zh": "10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。", "summary_en": "Demonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests. Estonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "summary_zh": "全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "body_en": "France Protests Spark Debate on Russian Interference Claims.\n\nHundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.\n\nDemonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests.\n\nEstonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "body_zh": "法国抗议潮引发「俄方干涉」说法之争。\n\n10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。\n\n全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。\n\n官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "url": "https://x.com/i/trending/2112296384745631848", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:03:55.000Z"}, {"id": "2112660061600309523", "domain": "国际", "title_en": "National Security Officials Quietly Prep States for Potential Midterm Interference", "title_zh": "美安全官员低调向多州通报中期选举风险", "hook_en": "A handful of U.S. national security veterans have spent months huddling with governors and lawmakers, mapping out responses to possible federal moves at polling places.", "hook_zh": "一小群国防部相关官员数月来悄然咨询约 10 个州的州长与议员，为投票站出现联邦部队等情景做准备。", "summary_en": "About 10 current and former Defense Department officials, some with experience countering authoritarianism abroad, have consulted with leaders in roughly 10 states on scenarios like federal troops or immigration agents at polls or fraud challenges. Speaking anonymously to avoid retaliation, they stress their nonpartisan work stems from concerns over federal overreach, targeting states with tight races that could decide Congress. The Washington Post report has drawn accusations of 'deep state' plotting from critics, while supporters see it as prudent election planning amid rising distrust between the Trump administration and parts of the security community.", "summary_zh": "约 10 名现任与前任官员，向两党选举官员与国会议员通报特朗普政府可能采取的行动，例如移民执法人员出现在投票站，或借舞弊指控试图否定结果。重点放在可能左右国会控制权的摇摆州；参与者称关切选举完整性，并因担心报复而匿名发声。反应尖锐对立：有人视之为必要预案，也有人质疑这群非选举产生人士的秘密角色，以及联邦与州权之间的紧张。", "body_en": "National Security Officials Quietly Prep States for Potential Midterm Interference.\n\nA handful of U.S. national security veterans have spent months huddling with governors and lawmakers, mapping out responses to possible federal moves at polling places.\n\nAbout 10 current and former Defense Department officials, some with experience countering authoritarianism abroad, have consulted with leaders in roughly 10 states on scenarios like federal troops or immigration agents at polls or fraud challenges.\n\nSpeaking anonymously to avoid retaliation, they stress their nonpartisan work stems from concerns over federal overreach, targeting states with tight races that could decide Congress. The Washington Post report has drawn accusations of 'deep state' plotting from critics, while supporters see it as prudent election planning amid rising distrust between the Trump administration and parts of the security community.", "body_zh": "美安全官员低调向多州通报中期选举风险。\n\n一小群国防部相关官员数月来悄然咨询约 10 个州的州长与议员，为投票站出现联邦部队等情景做准备。\n\n约 10 名现任与前任官员，向两党选举官员与国会议员通报特朗普政府可能采取的行动，例如移民执法人员出现在投票站，或借舞弊指控试图否定结果。\n\n重点放在可能左右国会控制权的摇摆州；参与者称关切选举完整性，并因担心报复而匿名发声。反应尖锐对立：有人视之为必要预案，也有人质疑这群非选举产生人士的秘密角色，以及联邦与州权之间的紧张。", "url": "https://x.com/i/trending/2112660061600309523", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:07:44.000Z"}, {"id": "2112893265104007427", "domain": "国际", "title_en": "Thread Reveals Groups Planning Responses to Potential Federal Actions Before Midterms", "title_zh": "帖文曝光组织在中期选举前讨论应对联邦行动", "hook_en": "A detailed X thread uncovered audio and video from democracy groups discussing when the federal government might cross into illegitimacy, raising eyebrows just before the November midterms.", "hook_zh": "一篇详尽的 X 帖文披露民主团体讨论联邦政府何时可能「越界」的音视频，临近 11 月中期选举引发关注。", "summary_en": "X user DataRepublican, real name Jennica Pounds, shared materials from the Renew to Thrive group and the United Democracy Alliance, which links with NGOs like Indivisible. The recordings outline 'redlines' such as invoking the Insurrection Act against peaceful protesters, with governors potentially refusing federal troops and networks stepping in. This coincides with a Washington Post report on current and former Pentagon officials advising 10 states on resisting possible federal moves near polling places. Reactions split between calls for investigation and defenses of the work as protecting elections, though the materials await independent verification.", "summary_zh": "X 用户 DataRepublican（真名 Jennica Pounds）分享了 Renew to Thrive 团体与联合民主联盟（关联 Indivisible 等 NGO）的材料。录音勾勒「红线」场景，例如对和平抗议者动用《叛乱法》，州长或拒绝联邦部队、网络介入响应。同期《华盛顿邮报》报道现任与前任五角大楼官员正为约 10 个州提供建议，以防范投票点附近可能的联邦举动。舆论分裂为要求调查与辩称属保卫选举，材料尚待独立核实。", "body_en": "Thread Reveals Groups Planning Responses to Potential Federal Actions Before Midterms.\n\nA detailed X thread uncovered audio and video from democracy groups discussing when the federal government might cross into illegitimacy, raising eyebrows just before the November midterms.\n\nX user DataRepublican, real name Jennica Pounds, shared materials from the Renew to Thrive group and the United Democracy Alliance, which links with NGOs like Indivisible. The recordings outline 'redlines' such as invoking the Insurrection Act against peaceful protesters, with governors potentially refusing federal troops and networks stepping in.\n\nThis coincides with a Washington Post report on current and former Pentagon officials advising 10 states on resisting possible federal moves near polling places. Reactions split between calls for investigation and defenses of the work as protecting elections, though the materials await independent verification.", "body_zh": "帖文曝光组织在中期选举前讨论应对联邦行动。\n\n一篇详尽的 X 帖文披露民主团体讨论联邦政府何时可能「越界」的音视频，临近 11 月中期选举引发关注。\n\nX 用户 DataRepublican（真名 Jennica Pounds）分享了 Renew to Thrive 团体与联合民主联盟（关联 Indivisible 等 NGO）的材料。录音勾勒「红线」场景，例如对和平抗议者动用《叛乱法》，州长或拒绝联邦部队、网络介入响应。\n\n同期《华盛顿邮报》报道现任与前任五角大楼官员正为约 10 个州提供建议，以防范投票点附近可能的联邦举动。舆论分裂为要求调查与辩称属保卫选举，材料尚待独立核实。", "url": "https://x.com/i/trending/2112893265104007427", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:32:37.000Z"}, {"id": "2112592169139855608", "domain": "国际", "title_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps", "title_zh": "匈牙利阻挠乌克兰与摩尔多瓦入盟谈判下一步", "hook_en": "Just days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.", "hook_zh": "乌克兰刚通过保护匈裔少数群体的法律数日，匈牙利却叫停乌、摩两国欧盟谈判下一阶段，外交官对沉默感到困惑。", "summary_en": "At a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move. This follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "summary_zh": "10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续联通、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。此前乌克兰 10 月 12 日通过少数群体保护法，总理 Péter Magyar 与泽连斯基会面试图重置关系，曾使更早集群得以开启。因入盟需全体一致，此次阻拦再次引发对匈牙利扩盟立场的质疑；观察人士指出，尽管已有沟通，决定仍未说明理由，各方感到沮丧。", "body_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps.\n\nJust days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.\n\nAt a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move.\n\nThis follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "body_zh": "匈牙利阻挠乌克兰与摩尔多瓦入盟谈判下一步。\n\n乌克兰刚通过保护匈裔少数群体的法律数日，匈牙利却叫停乌、摩两国欧盟谈判下一阶段，外交官对沉默感到困惑。\n\n10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续联通、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。\n\n此前乌克兰 10 月 12 日通过少数群体保护法，总理 Péter Magyar 与泽连斯基会面试图重置关系，曾使更早集群得以开启。因入盟需全体一致，此次阻拦再次引发对匈牙利扩盟立场的质疑；观察人士指出，尽管已有沟通，决定仍未说明理由，各方感到沮丧。", "url": "https://x.com/i/trending/2112592169139855608", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:18:54.000Z"}, {"id": "2112964655136354409", "domain": "国际", "title_en": "Poland Halts Ukraine Aid Over Lviv's Nationalist Figures Resolution", "title_zh": "因利沃夫纪念二战民族主义人物决议，波兰暂停对乌援助", "hook_en": "A regional council in Lviv declared 2027 a year to honor WWII nationalist leaders, just as Poland prepared a major aid shipment to Ukraine.", "hook_zh": "利沃夫地区议会宣布 2027 年为纪念二战民族主义领袖之年，正值波兰准备向乌克兰运送大批援助。", "summary_en": "The Lviv Regional Council voted on October 20 to commemorate Ukrainian Insurgent Army commander Roman Shukhevych and poet Oleh Olzhych, figures tied to Ukraine's independence struggle but also implicated in wartime mass killings of Poles, Jews, and others. Polish leaders, including Prime Minister Donald Tusk who called it unwise and harmful to Ukraine's EU path, responded by halting the aid package and banning the resolution's author from Poland and the Schengen area. Ukraine's Foreign Ministry distanced itself from the vote, urging dialogue to preserve wartime cooperation, as both nations work through back channels amid historical tensions.", "summary_zh": "利沃夫州议会 10 月 20 日表决纪念乌克兰起义军指挥官罗曼·舒赫维奇与诗人奥列赫·奥利日奇——二人既与独立斗争相关，也被指卷入战时对波兰人、犹太人等的屠杀。波兰总理图斯克等称此举不明智且有损乌克兰入欧路径，随即叫停援助包，并禁止决议推动者进入波兰与申根区。乌克兰外交部与表决保持距离，呼吁对话以维护战时合作；双方正通过幕后渠道处理历史张力。", "body_en": "Poland Halts Ukraine Aid Over Lviv's Nationalist Figures Resolution.\n\nA regional council in Lviv declared 2027 a year to honor WWII nationalist leaders, just as Poland prepared a major aid shipment to Ukraine.\n\nThe Lviv Regional Council voted on October 20 to commemorate Ukrainian Insurgent Army commander Roman Shukhevych and poet Oleh Olzhych, figures tied to Ukraine's independence struggle but also implicated in wartime mass killings of Poles, Jews, and others.\n\nPolish leaders, including Prime Minister Donald Tusk who called it unwise and harmful to Ukraine's EU path, responded by halting the aid package and banning the resolution's author from Poland and the Schengen area. Ukraine's Foreign Ministry distanced itself from the vote, urging dialogue to preserve wartime cooperation, as both nations work through back channels amid historical tensions.", "body_zh": "因利沃夫纪念二战民族主义人物决议，波兰暂停对乌援助。\n\n利沃夫地区议会宣布 2027 年为纪念二战民族主义领袖之年，正值波兰准备向乌克兰运送大批援助。\n\n利沃夫州议会 10 月 20 日表决纪念乌克兰起义军指挥官罗曼·舒赫维奇与诗人奥列赫·奥利日奇——二人既与独立斗争相关，也被指卷入战时对波兰人、犹太人等的屠杀。\n\n波兰总理图斯克等称此举不明智且有损乌克兰入欧路径，随即叫停援助包，并禁止决议推动者进入波兰与申根区。乌克兰外交部与表决保持距离，呼吁对话以维护战时合作；双方正通过幕后渠道处理历史张力。", "url": "https://x.com/i/trending/2112964655136354409", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:57:58.000Z"}, {"id": "2112460842902151394", "domain": "国际", "title_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters", "title_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击", "hook_en": "U.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.", "hook_zh": "美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。", "summary_en": "Rep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep. Brian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "summary_zh": "民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "body_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters.\n\nU.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.\n\nRep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep.\n\nBrian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "body_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击。\n\n美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。\n\n民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。\n\n网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "url": "https://x.com/i/trending/2112460842902151394", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T08:32:59.000Z"}, {"id": "2112773061082767722", "domain": "国际", "title_en": "Merz Rejects Ukraine Surrender as Threat to All Europe", "title_zh": "美情报称普京下令加大对北约欧洲的破坏行动", "hook_en": "German Chancellor Friedrich Merz drew a firm line: Ukraine's surrender would mean Europe's own capitulation. He shared this view at the Berlin Global Dialogue, amid rising Russian sabotage fears.", "hook_zh": "今年 8 月一架装有爆炸物的无人机袭击德国莱比锡机场一架乌克兰货机但未起爆，被指属于更广泛隐蔽行动的一部分。", "summary_en": "Merz declared that any surrender by Ukraine to Russia is off the table, as it would surrender Europe's security too. His words followed U.S. intelligence reports of Putin ordering stepped-up sabotage against NATO nations, including a foiled drone attack on Leipzig-Halle Airport targeting a Ukrainian aid plane. A Kremlin back-channel warning hinted at more strikes to come, prompting Germany to boost security and consider NATO's Article 5 if casualties had occurred. Merz called Russia's hybrid operations and societal influence Germany's top concern, framing Ukraine aid as vital to protecting the post-1990 European order.", "summary_zh": "美方情报称，因乌克兰和谈停滞及基辅深远打击，普京直接下令显著加强对欧洲北约国家的破坏活动。莱比锡事件被指向经塞尔维亚运送爆炸物的俄军情报单位，目标涉及军援；克里姆林宫后据称通过后门警告德国还将有更多袭击。德国已将军事破坏威胁调至“显著”，并讨论若造成伤亡是否触及北约第五条。俄方否认，北约仍在评估应对。", "body_en": "Putin Ordered Sabotage Campaign Against NATO, U.S. Intel Assesses.\n\nA drone packed with explosives struck a cargo plane at Germany's Leipzig-Halle Airport in August, but mercifully failed to detonate. U.S. intelligence now pins it on a personal order from Putin to ramp up covert attacks on NATO nations.\n\nThe Wall Street Journal investigation reveals Russian President Vladimir Putin directed the GRU military intelligence unit to intensify sabotage against NATO countries, targeting military aid shipments to Ukraine, infrastructure, and shipping to weaken European support. The Leipzig plot involved three drones aimed at an Antonov aircraft; one hit but didn't explode, averting disaster.\n\nGerman Chancellor Friedrich Merz warned of Russia's societal threat, noting mass casualties there could have triggered NATO's Article 5. Berlin blamed Moscow publicly, raised sabotage alerts, while Russia denies involvement.", "body_zh": "美情报称普京下令加大对北约欧洲的破坏行动。\n\n今年 8 月一架装有爆炸物的无人机袭击德国莱比锡机场一架乌克兰货机但未起爆，被指属于更广泛隐蔽行动的一部分。\n\n美方情报称，因乌克兰和谈停滞及基辅深远打击，普京直接下令显著加强对欧洲北约国家的破坏活动。莱比锡事件被指向经塞尔维亚运送爆炸物的俄军情报单位，目标涉及军援；克里姆林宫后据称通过后门警告德国还将有更多袭击。\n\n德国已将军事破坏威胁调至“显著”，并讨论若造成伤亡是否触及北约第五条。俄方否认，北约仍在评估应对。", "url": "https://x.com/i/trending/2112773061082767722", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T17:08:27.000Z"}, {"id": "2112501506905710732", "domain": "国际", "title_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims", "title_zh": "英波就美防长阿富汗盟友言论提出严正回应", "hook_en": "Pete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.", "hook_zh": "赫格塞思称喀布尔可见多国旗帜，但真正并肩作战者寥寥；英国与波兰领导人迅速反驳并缅怀本国阵亡者。", "summary_en": "During a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "summary_zh": "美防长 Pete Hegseth 在田纳西大学演讲称，鲜有北约盟友在阿富汗真正投入战斗，并调侃 ISAF 补丁意为“我看见美国人在打仗”。唐宁街强调英军阵亡 457 人，仅次于美国；波兰外长指出 44 名波军在加兹尼省牺牲。数据显示非美联军阵亡逾 1100 人。言论引发对盟友牺牲被低估的强烈不满。", "body_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims.\n\nPete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.\n\nDuring a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "body_zh": "英波就美防长阿富汗盟友言论提出严正回应。\n\n赫格塞思称喀布尔可见多国旗帜，但真正并肩作战者寥寥；英国与波兰领导人迅速反驳并缅怀本国阵亡者。\n\n美防长 Pete Hegseth 在田纳西大学演讲称，鲜有北约盟友在阿富汗真正投入战斗，并调侃 ISAF 补丁意为“我看见美国人在打仗”。唐宁街强调英军阵亡 457 人，仅次于美国；波兰外长指出 44 名波军在加兹尼省牺牲。\n\n数据显示非美联军阵亡逾 1100 人。言论引发对盟友牺牲被低估的强烈不满。", "url": "https://x.com/i/trending/2112501506905710732", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:10:22.000Z"}, {"id": "2112533926879125584", "domain": "国际", "title_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe", "title_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势", "hook_en": "In a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.", "hook_zh": "乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。", "summary_en": "Volodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion. Social media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "summary_zh": "泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "body_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe.\n\nIn a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.\n\nVolodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion.\n\nSocial media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "body_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势。\n\n乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。\n\n泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。\n\n社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "url": "https://x.com/i/trending/2112533926879125584", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T13:26:36.000Z"}, {"id": "2112749239679820040", "domain": "国际", "title_en": "CNN Reports Intense Internal Struggles in Trump's White House Ahead of Midterms", "title_zh": "CNN：中期选举前特朗普白宫内斗激烈", "hook_en": "A Trump ally described the White House atmosphere as brutally distrustful, saying 'You can't trust anybody here' amid fears of midterm losses.", "hook_zh": "一名特朗普盟友形容白宫氛围极度缺乏信任，称「这里谁都不能信」，并担忧中期选举失利。", "summary_en": "A CNN report cites administration officials and allies detailing power jockeying, blame-shifting, and toxicity inside the White House as Republicans brace for November's midterms. Recent signs include Kimberly Guilfoyle's ouster as ambassador to Greece and probes into disputes over Kennedy Center funding involving Alina Habba Mildon and Ric Grenell. White House spokesman Davis Ingle dismissed the claims as baseless speculation, insisting Trump stays focused on securing congressional majorities. Other outlets like The Washington Post echo themes of aides positioning for post-election roles.", "summary_zh": "CNN 援引政府官员与盟友，描述共和党备战 11 月中期之际白宫内权力争斗、甩锅与紧张气氛。近期迹象包括金伯利·吉尔福伊勒被免去驻希腊大使，以及围绕肯尼迪中心资金、牵涉阿丽娜·哈巴·米尔登与里克·格内尔的争议调查。白宫发言人戴维斯·英格尔称相关说法为无根据猜测，并称特朗普专注于保住国会多数。《华盛顿邮报》等亦提到助手们为选后角色卡位。", "body_en": "CNN Reports Intense Internal Struggles in Trump's White House Ahead of Midterms.\n\nA Trump ally described the White House atmosphere as brutally distrustful, saying 'You can't trust anybody here' amid fears of midterm losses.\n\nA CNN report cites administration officials and allies detailing power jockeying, blame-shifting, and toxicity inside the White House as Republicans brace for November's midterms. Recent signs include Kimberly Guilfoyle's ouster as ambassador to Greece and probes into disputes over Kennedy Center funding involving Alina Habba Mildon and Ric Grenell.\n\nWhite House spokesman Davis Ingle dismissed the claims as baseless speculation, insisting Trump stays focused on securing congressional majorities. Other outlets like The Washington Post echo themes of aides positioning for post-election roles.", "body_zh": "CNN：中期选举前特朗普白宫内斗激烈。\n\n一名特朗普盟友形容白宫氛围极度缺乏信任，称「这里谁都不能信」，并担忧中期选举失利。\n\nCNN 援引政府官员与盟友，描述共和党备战 11 月中期之际白宫内权力争斗、甩锅与紧张气氛。近期迹象包括金伯利·吉尔福伊勒被免去驻希腊大使，以及围绕肯尼迪中心资金、牵涉阿丽娜·哈巴·米尔登与里克·格内尔的争议调查。\n\n白宫发言人戴维斯·英格尔称相关说法为无根据猜测，并称特朗普专注于保住国会多数。《华盛顿邮报》等亦提到助手们为选后角色卡位。", "url": "https://x.com/i/trending/2112749239679820040", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T03:38:52.000Z"}, {"id": "2112384299999850805", "domain": "国际", "title_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally", "title_zh": "特朗普在堪萨斯集会警告或退出北约", "hook_en": "Thousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.", "hook_zh": "数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。", "summary_en": "At a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate. He criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "summary_zh": "在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "body_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally.\n\nThousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.\n\nAt a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate.\n\nHe criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "body_zh": "特朗普在堪萨斯集会警告或退出北约。\n\n数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。\n\n在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。\n\n他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "url": "https://x.com/i/trending/2112384299999850805", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T21:20:55.000Z"}, {"id": "2112462431087939712", "domain": "国际", "title_en": "South Korea Withdraws Embassy Staff from Ukraine Over North Korean POW Dispute", "title_zh": "韩因朝战俘纠纷撤回驻乌使馆约半数人员", "hook_en": "Two North Korean soldiers captured in Ukraine's brutal fighting now sit at the heart of a deepening rift between Seoul and Kyiv, prompting a partial pullback of embassy staff.", "hook_zh": "两名在乌克兰战场被俘的朝鲜士兵，成为首尔与基辅关系裂痕的核心，促使韩方部分撤回使馆人员。", "summary_en": "South Korea's Foreign Ministry announced it will withdraw about half its diplomatic personnel from Ukraine due to Kyiv's failure to resolve a dispute over two captured North Korean soldiers transferred to Seoul last month. The tensions erupted after President Zelenskyy publicly disclosed the transfer at the UN, which Seoul says breached a confidentiality agreement meant to protect the soldiers and their families. While consular services continue and channels for citizen evacuations remain open, the move underscores Seoul's frustration amid ongoing Russian airstrikes. Ukraine denies any secrecy pact and insists the issue is settled, keeping doors open for talks.", "summary_zh": "韩国外交部宣布，因基辅未能解决上月移交首尔的两名被俘朝鲜士兵相关争议，将撤回驻乌约半数外交人员。紧张在泽连斯基总统于联合国公开披露移交后升温，首尔称此举违反旨在保护士兵及其家属的保密约定。领事服务仍继续，公民撤离渠道保持畅通，此举凸显首尔在俄军持续空袭背景下的不满。乌方否认存在保密协议并坚称问题已解决，同时表示对话大门仍开。", "body_en": "South Korea Withdraws Embassy Staff from Ukraine Over North Korean POW Dispute.\n\nTwo North Korean soldiers captured in Ukraine's brutal fighting now sit at the heart of a deepening rift between Seoul and Kyiv, prompting a partial pullback of embassy staff.\n\nSouth Korea's Foreign Ministry announced it will withdraw about half its diplomatic personnel from Ukraine due to Kyiv's failure to resolve a dispute over two captured North Korean soldiers transferred to Seoul last month. The tensions erupted after President Zelenskyy publicly disclosed the transfer at the UN, which Seoul says breached a confidentiality agreement meant to protect the soldiers and their families.\n\nWhile consular services continue and channels for citizen evacuations remain open, the move underscores Seoul's frustration amid ongoing Russian airstrikes. Ukraine denies any secrecy pact and insists the issue is settled, keeping doors open for talks.", "body_zh": "韩因朝战俘纠纷撤回驻乌使馆约半数人员。\n\n两名在乌克兰战场被俘的朝鲜士兵，成为首尔与基辅关系裂痕的核心，促使韩方部分撤回使馆人员。\n\n韩国外交部宣布，因基辅未能解决上月移交首尔的两名被俘朝鲜士兵相关争议，将撤回驻乌约半数外交人员。紧张在泽连斯基总统于联合国公开披露移交后升温，首尔称此举违反旨在保护士兵及其家属的保密约定。\n\n领事服务仍继续，公民撤离渠道保持畅通，此举凸显首尔在俄军持续空袭背景下的不满。乌方否认存在保密协议并坚称问题已解决，同时表示对话大门仍开。", "url": "https://x.com/i/trending/2112462431087939712", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T13:25:27.000Z"}, {"id": "2112952170798805319", "domain": "国际", "title_en": "Officials Probe Foreign Influence in French Riots Disinformation", "title_zh": "官员调查法国骚乱虚假信息中的外部势力影响", "hook_en": "Amid burning barricades and clashing crowds in Paris, videos of masked protesters waving antifascist banners spread fast—now officials suspect pro-Russian and far-right accounts amplified them to stir chaos.", "hook_zh": "巴黎街垒燃烧、人群冲突之际，蒙面抗议者挥舞反法西斯旗帜的视频迅速传播——官员怀疑亲俄与极右账号放大内容、煽动混乱。", "summary_en": "European security officials are investigating how pro-Russian, far-right social media accounts, along with suspected Iranian and Algerian operations, spread violent riot videos during France's recent unrest over education and living costs. The clashes escalated into arson and looting in Paris and other cities over the October 17 weekend, with regulators examining platform algorithms for boosting disinformation and hate speech. While President Macron sees no foreign hand in the events themselves, critics like Michael Shellenberger call the focus partisan deflection from real domestic issues, as probes continue into whether footage was real or fabricated.", "summary_zh": "欧洲安全官员正在调查亲俄、极右社交媒体账号，以及疑似伊朗、阿尔及利亚相关运作，如何在法国因教育与生活成本引发的近期动荡中传播暴力骚乱视频。冲突于 10 月 17 日周末在巴黎等地升级为纵火与抢劫，监管机构审视平台算法是否助推虚假信息与仇恨言论。马克龙总统认为事件本身未见外部黑手，但批评者如迈克尔·谢伦伯格称聚焦外部是对本国问题的党派式转移；调查仍在核实画面真伪。", "body_en": "Officials Probe Foreign Influence in French Riots Disinformation.\n\nAmid burning barricades and clashing crowds in Paris, videos of masked protesters waving antifascist banners spread fast—now officials suspect pro-Russian and far-right accounts amplified them to stir chaos.\n\nEuropean security officials are investigating how pro-Russian, far-right social media accounts, along with suspected Iranian and Algerian operations, spread violent riot videos during France's recent unrest over education and living costs.\n\nThe clashes escalated into arson and looting in Paris and other cities over the October 17 weekend, with regulators examining platform algorithms for boosting disinformation and hate speech. While President Macron sees no foreign hand in the events themselves, critics like Michael Shellenberger call the focus partisan deflection from real domestic issues, as probes continue into whether footage was real or fabricated.", "body_zh": "官员调查法国骚乱虚假信息中的外部势力影响。\n\n巴黎街垒燃烧、人群冲突之际，蒙面抗议者挥舞反法西斯旗帜的视频迅速传播——官员怀疑亲俄与极右账号放大内容、煽动混乱。\n\n欧洲安全官员正在调查亲俄、极右社交媒体账号，以及疑似伊朗、阿尔及利亚相关运作，如何在法国因教育与生活成本引发的近期动荡中传播暴力骚乱视频。\n\n冲突于 10 月 17 日周末在巴黎等地升级为纵火与抢劫，监管机构审视平台算法是否助推虚假信息与仇恨言论。马克龙总统认为事件本身未见外部黑手，但批评者如迈克尔·谢伦伯格称聚焦外部是对本国问题的党派式转移；调查仍在核实画面真伪。", "url": "https://x.com/i/trending/2112952170798805319", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:07:39.000Z"}, {"id": "2112897433646641610", "domain": "体育", "title_en": "The Times Apologizes to FIFA and Infantino After Retracting Salary Claims", "title_zh": "《泰晤士报》撤回薪酬报道并向 FIFA 与因凡蒂诺致歉", "hook_en": "The Times pulled back a major story on FIFA president Gianni Infantino's alleged secret salary, issuing a full apology to him and the organization.", "hook_zh": "《泰晤士报》收回关于 FIFA 主席詹尼·因凡蒂诺所谓「秘密薪酬」的重磅报道，并向其本人及组织正式道歉。", "summary_en": "On October 13, 2026, the British newspaper reported that Infantino received an undeclared second salary not listed in FIFA's filings, along with claims about a Miami property purchase and ties to Shadi LLC. The paper later corrected these errors, explaining that Swiss rules exclude expenses from compensation reports, Infantino did not buy the property, and neither he nor his family owns or controls Shadi LLC. FIFA accepted the apology but pointed to a broader effort to undermine them, especially as Infantino eyes re-election next year with candidacy deadlines nearing in November.", "summary_zh": "2026 年 10 月 13 日，这家英国报纸曾报道因凡蒂诺领取未在 FIFA 申报材料中列明的第二份薪酬，并涉及其在迈阿密购房及与 Shadi LLC 的关联。该报随后更正错误，说明瑞士规则可将费用排除在薪酬披露之外、因凡蒂诺并未购买该房产，且其本人与家人既不拥有也不控制 Shadi LLC。FIFA 接受道歉，但指称存在更广泛的抹黑努力；因凡蒂诺明年寻求连任，候选人报名截止日期临近 11 月。", "body_en": "The Times Apologizes to FIFA and Infantino After Retracting Salary Claims.\n\nThe Times pulled back a major story on FIFA president Gianni Infantino's alleged secret salary, issuing a full apology to him and the organization.\n\nOn October 13, 2026, the British newspaper reported that Infantino received an undeclared second salary not listed in FIFA's filings, along with claims about a Miami property purchase and ties to Shadi LLC.\n\nThe paper later corrected these errors, explaining that Swiss rules exclude expenses from compensation reports, Infantino did not buy the property, and neither he nor his family owns or controls Shadi LLC. FIFA accepted the apology but pointed to a broader effort to undermine them, especially as Infantino eyes re-election next year with candidacy deadlines nearing in November.", "body_zh": "《泰晤士报》撤回薪酬报道并向 FIFA 与因凡蒂诺致歉。\n\n《泰晤士报》收回关于 FIFA 主席詹尼·因凡蒂诺所谓「秘密薪酬」的重磅报道，并向其本人及组织正式道歉。\n\n2026 年 10 月 13 日，这家英国报纸曾报道因凡蒂诺领取未在 FIFA 申报材料中列明的第二份薪酬，并涉及其在迈阿密购房及与 Shadi LLC 的关联。\n\n该报随后更正错误，说明瑞士规则可将费用排除在薪酬披露之外、因凡蒂诺并未购买该房产，且其本人与家人既不拥有也不控制 Shadi LLC。FIFA 接受道歉，但指称存在更广泛的抹黑努力；因凡蒂诺明年寻求连任，候选人报名截止日期临近 11 月。", "url": "https://x.com/i/trending/2112897433646641610", "category": "News", "topics": ["Sports"], "updated_at": "2026-10-21T16:42:23.000Z"}, {"id": "2112930908437426481", "domain": "体育", "title_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment", "title_zh": "勒布朗热麦吐槽尼克斯「冠军哨」", "hook_en": "As the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.", "hook_zh": "尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。", "summary_en": "During the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists. His remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "summary_zh": "尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "body_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment.\n\nAs the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.\n\nDuring the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists.\n\nHis remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "body_zh": "勒布朗热麦吐槽尼克斯「冠军哨」。\n\n尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。\n\n尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。\n\n他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "url": "https://x.com/i/trending/2112930908437426481", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T15:43:54.000Z"}, {"id": "2112527510105919970", "domain": "体育", "title_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs", "title_zh": "前 NFL 球员指控裁判偏袒酋长队操控比赛", "hook_en": "Breiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.", "hook_zh": "Breiden Fehoko 在播客上直指他认为的酋长队末节「照顾球」，戳中多年对手球迷的积怨。", "summary_en": "Former Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs. Critics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "summary_zh": "前闪电队防守截锋 Breiden Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节给堪萨斯城「幽灵判罚」扳动胶着比赛。他称落后时点球常救酋长，是「嘲弄」，并要求季后赛裁判保持中立。批评者指出其样本极小——仅打过一场对酋长、生涯 19 场出场——粉丝则搬出 2022 年 AFC 冠军赛等作为「证据」。争论凸显对 NFL 执法的持续不满，但缺乏操纵的硬证据。", "body_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs.\n\nBreiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.\n\nFormer Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs.\n\nCritics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "body_zh": "前 NFL 球员指控裁判偏袒酋长队操控比赛。\n\nBreiden Fehoko 在播客上直指他认为的酋长队末节「照顾球」，戳中多年对手球迷的积怨。\n\n前闪电队防守截锋 Breiden Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节给堪萨斯城「幽灵判罚」扳动胶着比赛。他称落后时点球常救酋长，是「嘲弄」，并要求季后赛裁判保持中立。\n\n批评者指出其样本极小——仅打过一场对酋长、生涯 19 场出场——粉丝则搬出 2022 年 AFC 冠军赛等作为「证据」。争论凸显对 NFL 执法的持续不满，但缺乏操纵的硬证据。", "url": "https://x.com/i/trending/2112527510105919970", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T02:52:40.000Z"}, {"id": "2112281281501528167", "domain": "体育", "title_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves", "title_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头", "hook_en": "Kyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.", "hook_zh": "凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。", "summary_en": "The Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No. 1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "summary_zh": "这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "body_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves.\n\nKyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.\n\nThe Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No.\n\n1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "body_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头。\n\n凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。\n\n这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。\n\n在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "url": "https://x.com/i/trending/2112281281501528167", "category": "Sports", "topics": [], "updated_at": "2026-10-20T15:54:00.000Z"}, {"id": "2112804232634187907", "domain": "体育", "title_en": "NBA Season Tips Off with Thunder Victory and Fan Joy", "title_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾", "hook_en": "Fans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.", "hook_zh": "2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。", "summary_en": "The season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama. Other games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "summary_zh": "赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "body_en": "NBA Season Tips Off with Thunder Victory and Fan Joy.\n\nFans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.\n\nThe season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama.\n\nOther games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "body_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾。\n\n2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。\n\n赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。\n\n另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "url": "https://x.com/i/trending/2112804232634187907", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:17:07.000Z"}, {"id": "2112801176995467757", "domain": "体育", "title_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts", "title_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相", "hook_en": "LeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.", "hook_zh": "勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。", "summary_en": "The Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration. Tyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "summary_zh": "费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "body_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts.\n\nLeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.\n\nThe Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration.\n\nTyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "body_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相。\n\n勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。\n\n费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。\n\n赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "url": "https://x.com/i/trending/2112801176995467757", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:06:29.000Z"}, {"id": "2112718297158332458", "domain": "体育", "title_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener", "title_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛", "hook_en": "On a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.", "hook_zh": "底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。", "summary_en": "The league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers. While some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "summary_zh": "2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "body_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener.\n\nOn a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.\n\nThe league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers.\n\nWhile some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "body_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛。\n\n底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。\n\n2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。\n\n部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "url": "https://x.com/i/trending/2112718297158332458", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T01:36:46.000Z"}, {"id": "2112952165522432362", "domain": "体育", "title_en": "Brewers Apologize to Timeless Ticket Holders Over World Series Seating", "title_zh": "酿酒人队向「Timeless Ticket」持有人致歉并澄清世界大赛座位", "hook_en": "Longtime Brewers fans who bought special 'Timeless Tickets' back in 2015 finally got their shot at World Series seats—but not without some seating mix-ups and heartfelt apologies from the team.", "hook_zh": "2015 年购买「Timeless Ticket」的老球迷终于等到世界大赛入场机会——却因座位安排混乱收到球队诚恳道歉。", "summary_en": "The Milwaukee Brewers emailed 'Timeless Ticket' holders on October 20, clarifying redemptions for the 2026 World Series and apologizing for confusion over upper-level or standing-room options offered initially. These $1,000 bronze tickets, sold in limited numbers since 2015, promised the best available seats at any future home game, including playoffs. The team decided World Series tickets won't count against the one-time redemption, letting holders save their original tickets for later while still attending this year's games. Fans reacted with a mix of appreciation for the resolution and frustration over the handling, as President Rick Schlesinger admitted they fell short of the program's spirit.", "summary_zh": "密尔沃基酿酒人队于 10 月 20 日致信「Timeless Ticket」持有人，澄清 2026 年世界大赛兑换规则，并为最初提供上层或站席选项造成的困惑致歉。这些自 2015 年起限量发售的 1000 美元铜色票，承诺在任何未来主场比赛（含季后赛）提供当时最佳可用座位。球队决定世界大赛门票不计入一次性兑换，持有人可保留原票以后再用，同时仍可观看本届比赛。球迷对解决方案有赞有怨；总裁里克·施莱辛格承认未达项目初衷。", "body_en": "Brewers Apologize to Timeless Ticket Holders Over World Series Seating.\n\nLongtime Brewers fans who bought special 'Timeless Tickets' back in 2015 finally got their shot at World Series seats—but not without some seating mix-ups and heartfelt apologies from the team.\n\nThe Milwaukee Brewers emailed 'Timeless Ticket' holders on October 20, clarifying redemptions for the 2026 World Series and apologizing for confusion over upper-level or standing-room options offered initially. These $1,000 bronze tickets, sold in limited numbers since 2015, promised the best available seats at any future home game, including playoffs.\n\nThe team decided World Series tickets won't count against the one-time redemption, letting holders save their original tickets for later while still attending this year's games. Fans reacted with a mix of appreciation for the resolution and frustration over the handling, as President Rick Schlesinger admitted they fell short of the program's spirit.", "body_zh": "酿酒人队向「Timeless Ticket」持有人致歉并澄清世界大赛座位。\n\n2015 年购买「Timeless Ticket」的老球迷终于等到世界大赛入场机会——却因座位安排混乱收到球队诚恳道歉。\n\n密尔沃基酿酒人队于 10 月 20 日致信「Timeless Ticket」持有人，澄清 2026 年世界大赛兑换规则，并为最初提供上层或站席选项造成的困惑致歉。这些自 2015 年起限量发售的 1000 美元铜色票，承诺在任何未来主场比赛（含季后赛）提供当时最佳可用座位。\n\n球队决定世界大赛门票不计入一次性兑换，持有人可保留原票以后再用，同时仍可观看本届比赛。球迷对解决方案有赞有怨；总裁里克·施莱辛格承认未达项目初衷。", "url": "https://x.com/i/trending/2112952165522432362", "category": "Sports", "topics": ["MLB"], "updated_at": "2026-10-21T17:07:58.000Z"}, {"id": "2112620322600223204", "domain": "体育", "title_en": "FIFA Explores Himalaya Cup for Regional South Asian Football", "title_zh": "国际足联探讨创办南亚「喜马拉雅杯」", "hook_en": "Gianni Infantino donned traditional Bhutanese attire alongside local players and officials, sparking early talks on a new tournament to boost football in the Himalayas.", "hook_zh": "詹尼·因凡蒂诺身着不丹传统服饰，与当地球员和官员合影，并就提升喜马拉雅地区足球的新赛事展开早期讨论。", "summary_en": "During his recent visit to Bhutan, FIFA President Gianni Infantino discussed football development, leading to proposals for a Himalaya Cup involving nations like Nepal, Bhutan, India, Pakistan, China-Tibet, Maldives, and Sri Lanka. The tournament aims to provide systematic growth opportunities for South Asian football, building on FIFA's support for infrastructure and youth programs in Bhutan, including visits to Changlimithang Stadium and meetings with the prime minister and U-15 team. While fans show enthusiasm for more matches, questions linger about its fit with events like the SAFF Championship, and no final decision has been made as talks continue.", "summary_zh": "国际足联主席詹尼·因凡蒂诺近日访问不丹，讨论足球发展，并催生「喜马拉雅杯」构想，潜在参与方包括尼泊尔、不丹、印度、巴基斯坦、中国西藏、马尔代夫与斯里兰卡等。赛事旨在为南亚足球提供系统性成长机会，并建立在国际足联对不丹基建与青训支持之上，包括走访昌利米塘体育场、会见总理与 U-15 队。球迷对更多比赛表示期待，但与 SAFF 锦标赛等现有赛事如何衔接仍存疑问；会谈仍在继续，尚未最终拍板。", "body_en": "FIFA Explores Himalaya Cup for Regional South Asian Football.\n\nGianni Infantino donned traditional Bhutanese attire alongside local players and officials, sparking early talks on a new tournament to boost football in the Himalayas.\n\nDuring his recent visit to Bhutan, FIFA President Gianni Infantino discussed football development, leading to proposals for a Himalaya Cup involving nations like Nepal, Bhutan, India, Pakistan, China-Tibet, Maldives, and Sri Lanka.\n\nThe tournament aims to provide systematic growth opportunities for South Asian football, building on FIFA's support for infrastructure and youth programs in Bhutan, including visits to Changlimithang Stadium and meetings with the prime minister and U-15 team. While fans show enthusiasm for more matches, questions linger about its fit with events like the SAFF Championship, and no final decision has been made as talks continue.", "body_zh": "国际足联探讨创办南亚「喜马拉雅杯」。\n\n詹尼·因凡蒂诺身着不丹传统服饰，与当地球员和官员合影，并就提升喜马拉雅地区足球的新赛事展开早期讨论。\n\n国际足联主席詹尼·因凡蒂诺近日访问不丹，讨论足球发展，并催生「喜马拉雅杯」构想，潜在参与方包括尼泊尔、不丹、印度、巴基斯坦、中国西藏、马尔代夫与斯里兰卡等。\n\n赛事旨在为南亚足球提供系统性成长机会，并建立在国际足联对不丹基建与青训支持之上，包括走访昌利米塘体育场、会见总理与 U-15 队。球迷对更多比赛表示期待，但与 SAFF 锦标赛等现有赛事如何衔接仍存疑问；会谈仍在继续，尚未最终拍板。", "url": "https://x.com/i/trending/2112620322600223204", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-20T19:09:02.000Z"}, {"id": "2112801174256542152", "domain": "体育", "title_en": "Elina Svitolina and Gael Monfils Announce Marriage Split Amid Tennis Careers End", "title_zh": "斯维托丽娜与蒙菲尔斯宣布婚姻结束，网球生涯亦近尾声", "hook_en": "While Gael Monfils cared for their four-year-old daughter Skai in Dubai, Elina Svitolina called from tournaments in China to share her decision to end their marriage.", "hook_zh": "蒙菲尔斯在迪拜照顾四岁女儿斯凯期间，斯维托丽娜从中国巡回赛打来电话，告知结束婚姻的决定。", "summary_en": "The Ukrainian tennis star and French player, married since 2021, posted a joint Instagram announcement on October 19, with Svitolina citing over four years of war in Ukraine as shifting her priorities and needing to find her way back to herself. She stressed no one is to blame, their family continues, and later clarified the war was just one factor in a complex situation, while expressing deep love and respect for Monfils. Monfils, 40, retired abruptly on October 5 by leaving anti-doping lists, a move linked to the personal news; both have asked for privacy and kindness as they focus on daughter Skai's well-being amid divided online reactions.", "summary_zh": "这对自 2021 年结婚的乌克兰网球明星与法国球员于 10 月 19 日在 Instagram 联合发声明；斯维托丽娜称乌克兰战火逾四年改变了她的优先事项，需要找回自我。她强调无人应受指责、家庭仍在，并澄清战争只是复杂局面中的因素之一，同时对蒙菲尔斯表达深爱与尊重。40 岁的蒙菲尔斯于 10 月 5 日突然退出反兴奋剂名册宣布退役，与此私人消息相关；双方请求外界给予隐私与善意，聚焦女儿福祉，网上反应褒贬不一。", "body_en": "Elina Svitolina and Gael Monfils Announce Marriage Split Amid Tennis Careers End.\n\nWhile Gael Monfils cared for their four-year-old daughter Skai in Dubai, Elina Svitolina called from tournaments in China to share her decision to end their marriage.\n\nThe Ukrainian tennis star and French player, married since 2021, posted a joint Instagram announcement on October 19, with Svitolina citing over four years of war in Ukraine as shifting her priorities and needing to find her way back to herself.\n\nShe stressed no one is to blame, their family continues, and later clarified the war was just one factor in a complex situation, while expressing deep love and respect for Monfils. Monfils, 40, retired abruptly on October 5 by leaving anti-doping lists, a move linked to the personal news; both have asked for privacy and kindness as they focus on daughter Skai's well-being amid divided online reactions.", "body_zh": "斯维托丽娜与蒙菲尔斯宣布婚姻结束，网球生涯亦近尾声。\n\n蒙菲尔斯在迪拜照顾四岁女儿斯凯期间，斯维托丽娜从中国巡回赛打来电话，告知结束婚姻的决定。\n\n这对自 2021 年结婚的乌克兰网球明星与法国球员于 10 月 19 日在 Instagram 联合发声明；斯维托丽娜称乌克兰战火逾四年改变了她的优先事项，需要找回自我。\n\n她强调无人应受指责、家庭仍在，并澄清战争只是复杂局面中的因素之一，同时对蒙菲尔斯表达深爱与尊重。40 岁的蒙菲尔斯于 10 月 5 日突然退出反兴奋剂名册宣布退役，与此私人消息相关；双方请求外界给予隐私与善意，聚焦女儿福祉，网上反应褒贬不一。", "url": "https://x.com/i/trending/2112801174256542152", "category": "Sports", "topics": ["Tennis"], "updated_at": "2026-10-21T17:07:29.000Z"}, {"id": "2112506238546178093", "domain": "体育", "title_en": "FIFA Suspends Egypt Coach and Brother After World Cup Referee Criticism", "title_zh": "因批评裁判，FIFA 禁赛埃及主帅及其兄长", "hook_en": "After Egypt's heartbreaking 3-2 loss to Argentina in the 2026 World Cup round of 16, coach Hossam Hassan's pointed X gesture toward cameras captured the raw frustration of the moment.", "hook_zh": "埃及在 2026 世界杯十六强 3-2 惜败阿根廷后，主帅霍萨姆·哈桑朝镜头做出尖锐手势，道尽当场沮丧。", "summary_en": "FIFA handed three-match bans to Egypt head coach Hossam Hassan and his twin brother Ibrahim, the national team manager, plus a five-match suspension to forward Mostafa Zico, following their public criticism of the referee in the July 7 defeat in Atlanta. The sanctions stem from a disallowed goal, an unawarded penalty at 2-2, and heated post-match reactions, including Zico's bias accusations. The Egyptian FA is reviewing options for an appeal, while Hossam called the ban 'an honour' and left it to God; the penalties could affect Africa Cup of Nations qualifiers. Egypt's historic knockout run ended amid debates over refereeing in big matches.", "summary_zh": "FIFA 对埃及主帅霍萨姆·哈桑及其孪生兄长、国家队经理易卜拉欣各禁赛三场，前锋穆斯塔法·齐科禁赛五场，事由是他们对 7 月 7 日亚特兰大一役裁判公开批评。处罚源于进球被吹、2-2 时未判点球及赛后激烈反应，齐科曾指控裁判偏袒。埃及足协正评估上诉；霍萨姆称禁赛「是一种荣誉」并交托真主。处罚可能影响非洲杯预选赛。埃及历史性淘汰赛之旅在裁判争议中结束。", "body_en": "FIFA Suspends Egypt Coach and Brother After World Cup Referee Criticism.\n\nAfter Egypt's heartbreaking 3-2 loss to Argentina in the 2026 World Cup round of 16, coach Hossam Hassan's pointed X gesture toward cameras captured the raw frustration of the moment.\n\nFIFA handed three-match bans to Egypt head coach Hossam Hassan and his twin brother Ibrahim, the national team manager, plus a five-match suspension to forward Mostafa Zico, following their public criticism of the referee in the July 7 defeat in Atlanta. The sanctions stem from a disallowed goal, an unawarded penalty at 2-2, and heated post-match reactions, including Zico's bias accusations.\n\nThe Egyptian FA is reviewing options for an appeal, while Hossam called the ban 'an honour' and left it to God; the penalties could affect Africa Cup of Nations qualifiers. Egypt's historic knockout run ended amid debates over refereeing in big matches.", "body_zh": "因批评裁判，FIFA 禁赛埃及主帅及其兄长。\n\n埃及在 2026 世界杯十六强 3-2 惜败阿根廷后，主帅霍萨姆·哈桑朝镜头做出尖锐手势，道尽当场沮丧。\n\nFIFA 对埃及主帅霍萨姆·哈桑及其孪生兄长、国家队经理易卜拉欣各禁赛三场，前锋穆斯塔法·齐科禁赛五场，事由是他们对 7 月 7 日亚特兰大一役裁判公开批评。处罚源于进球被吹、2-2 时未判点球及赛后激烈反应，齐科曾指控裁判偏袒。\n\n埃及足协正评估上诉；霍萨姆称禁赛「是一种荣誉」并交托真主。处罚可能影响非洲杯预选赛。埃及历史性淘汰赛之旅在裁判争议中结束。", "url": "https://x.com/i/trending/2112506238546178093", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-20T18:57:06.000Z"}, {"id": "2112839270939480210", "domain": "体育", "title_en": "Fans Debate Sehwag's Chances in 2003 World Cup Final", "title_zh": "粉丝重议 2003 年世界杯决赛中赛义夫的追分可能", "hook_en": "A clip from the 2003 Cricket World Cup final brings back memories of Virender Sehwag's gritty 82 against Australia's massive 359. Fans now question if anyone truly believed India could chase it down.", "hook_zh": "一段 2003 板球世界杯决赛片段带回维伦德·赛义夫在澳大利亚高达 359 分面前打出坚韧 82 分的记忆；粉丝追问当时是否真有人相信印度能追上。", "summary_en": "In Johannesburg's Wanderers Stadium, Australia racked up 359 for 2, powered by Ricky Ponting's unbeaten 140 and Damien Martyn's 88, while India collapsed to 234 in 39.2 overs. Sehwag top-scored with 82 before a run-out, but many fans say the match was lost early, especially after Sachin Tendulkar's quick dismissal for 4, with no real belief in a miracle chase. Others recall fleeting hope while Sehwag batted or during rain breaks under Duckworth-Lewis, noting the era's rarity of big chases and Australia's dominance. The clip revives nostalgia, blending on-field drama with debates over how time warps those tense moments.", "summary_zh": "在约翰内斯堡万德勒斯球场，澳大利亚以 2 分 359 分收官，里基·庞廷未出局 140 分、达米安·马廷 88 分；印度 39.2 轮仅得 234 分。赛义夫以 82 分居首却遭跑出局，许多粉丝认为尤其在萨钦·腾杜尔卡仅得 4 分早早出局后，比赛早早失去悬念，几乎无人相信奇迹追分。也有人记得赛义夫在场或雨中达克沃斯—刘易斯中断时的短暂希望，并指出那个时代大比分追分罕见、澳队统治力极强。片段唤起怀旧，也混杂着时间如何改写紧张瞬间的争论。", "body_en": "Fans Debate Sehwag's Chances in 2003 World Cup Final.\n\nA clip from the 2003 Cricket World Cup final brings back memories of Virender Sehwag's gritty 82 against Australia's massive 359. Fans now question if anyone truly believed India could chase it down.\n\nIn Johannesburg's Wanderers Stadium, Australia racked up 359 for 2, powered by Ricky Ponting's unbeaten 140 and Damien Martyn's 88, while India collapsed to 234 in 39.2 overs. Sehwag top-scored with 82 before a run-out, but many fans say the match was lost early, especially after Sachin Tendulkar's quick dismissal for 4, with no real belief in a miracle chase.\n\nOthers recall fleeting hope while Sehwag batted or during rain breaks under Duckworth-Lewis, noting the era's rarity of big chases and Australia's dominance. The clip revives nostalgia, blending on-field drama with debates over how time warps those tense moments.", "body_zh": "粉丝重议 2003 年世界杯决赛中赛义夫的追分可能。\n\n一段 2003 板球世界杯决赛片段带回维伦德·赛义夫在澳大利亚高达 359 分面前打出坚韧 82 分的记忆；粉丝追问当时是否真有人相信印度能追上。\n\n在约翰内斯堡万德勒斯球场，澳大利亚以 2 分 359 分收官，里基·庞廷未出局 140 分、达米安·马廷 88 分；印度 39.2 轮仅得 234 分。赛义夫以 82 分居首却遭跑出局，许多粉丝认为尤其在萨钦·腾杜尔卡仅得 4 分早早出局后，比赛早早失去悬念，几乎无人相信奇迹追分。\n\n也有人记得赛义夫在场或雨中达克沃斯—刘易斯中断时的短暂希望，并指出那个时代大比分追分罕见、澳队统治力极强。片段唤起怀旧，也混杂着时间如何改写紧张瞬间的争论。", "url": "https://x.com/i/trending/2112839270939480210", "category": "Sports", "topics": ["Cricket"], "updated_at": "2026-10-21T11:57:55.000Z"}, {"id": "2112913094968000571", "domain": "体育", "title_en": "Giannis Debuts for Heat Against Timberwolves in Season Opener", "title_zh": "字母哥热火首秀对阵森林狼，揭幕战开启", "hook_en": "Giannis Antetokounmpo steps onto the Kaseya Center court for the first time as a Miami Heat player, teaming up with Bam Adebayo in a matchup full of fresh energy.", "hook_zh": "扬尼斯·阿德托昆博首次以迈阿密热火球员身份踏上卡塞亚中心球场，与巴姆·阿德巴约并肩，充满新鲜感。", "summary_en": "The Heat host the Timberwolves tonight at 7:30 p.m. ET on ESPN, marking Giannis's debut after his blockbuster trade from Milwaukee that sent Tyler Herro, Jaime Jaquez Jr., Kel'el Ware, Kasparas Jakucionis, and picks to the Bucks in exchange for the two-time MVP and Bobby Portis. Minnesota counters with new backcourt duo LaMelo Ball and Anthony Edwards following their multi-team deal. Giannis shared his excitement about playing with Bam, noting their matching birthdays and brotherly vibe, while both teams hype the night with game-day posts and fans anticipate a thrilling start to the 2026-27 season.", "summary_zh": "热火今晚美东时间 7:30 在 ESPN 主场迎战森林狼，标志着字母哥重磅交易后的首秀——密尔沃基雄鹿用这位两届 MVP 与鲍比·波蒂斯换来泰勒·希罗、海梅·哈克兹二世、凯勒尔·韦尔、卡斯帕拉斯·亚库乔尼斯及选秀权。明尼苏达则以拉梅洛·鲍尔与安东尼·爱德华兹组成新后场双核。扬尼斯表达与巴姆搭档的兴奋，提到两人同生日与兄弟般默契；双方用比赛日动态造势，球迷期待 2026-27 赛季精彩开局。", "body_en": "Giannis Debuts for Heat Against Timberwolves in Season Opener.\n\nGiannis Antetokounmpo steps onto the Kaseya Center court for the first time as a Miami Heat player, teaming up with Bam Adebayo in a matchup full of fresh energy.\n\nThe Heat host the Timberwolves tonight at 7:30 p.m. ET on ESPN, marking Giannis's debut after his blockbuster trade from Milwaukee that sent Tyler Herro, Jaime Jaquez Jr., Kel'el Ware, Kasparas Jakucionis, and picks to the Bucks in exchange for the two-time MVP and Bobby Portis.\n\nMinnesota counters with new backcourt duo LaMelo Ball and Anthony Edwards following their multi-team deal. Giannis shared his excitement about playing with Bam, noting their matching birthdays and brotherly vibe, while both teams hype the night with game-day posts and fans anticipate a thrilling start to the 2026-27 season.", "body_zh": "字母哥热火首秀对阵森林狼，揭幕战开启。\n\n扬尼斯·阿德托昆博首次以迈阿密热火球员身份踏上卡塞亚中心球场，与巴姆·阿德巴约并肩，充满新鲜感。\n\n热火今晚美东时间 7:30 在 ESPN 主场迎战森林狼，标志着字母哥重磅交易后的首秀——密尔沃基雄鹿用这位两届 MVP 与鲍比·波蒂斯换来泰勒·希罗、海梅·哈克兹二世、凯勒尔·韦尔、卡斯帕拉斯·亚库乔尼斯及选秀权。\n\n明尼苏达则以拉梅洛·鲍尔与安东尼·爱德华兹组成新后场双核。扬尼斯表达与巴姆搭档的兴奋，提到两人同生日与兄弟般默契；双方用比赛日动态造势，球迷期待 2026-27 赛季精彩开局。", "url": "https://x.com/i/trending/2112913094968000571", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T18:36:47.000Z"}, {"id": "2112826877455053262", "domain": "娱乐", "title_en": "India Adds Three Sites to UNESCO World Heritage Tentative List", "title_zh": "印度新增三处遗址进入联合国教科文组织世界遗产预备名单", "hook_en": "From bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.", "hook_zh": "从安达曼冒泡的泥火山，到马哈纳迪河沿岸古寺，三处印度遗产向全球认可又近一步。", "summary_en": "India's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh. These sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "summary_zh": "印度常驻联合国教科文组织代表团于 2026 年 10 月 20 日宣布，将安达曼-尼科巴群岛的巴拉唐岩溶泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦的希尔普尔文化考古景观列入预备名单。这些地点既有活火山、石灰岩洞穴等独特地质，也有体现印度教、佛教与耆那教遗产及多信仰共处的历史寺庙。联邦部长 Gajendra Singh Shekhawat 称赞希尔普尔在艺术、建筑、灵性与学问上的传统；印度目前已有 45 处列入世界遗产名录。", "body_en": "India Adds Three Sites to UNESCO World Heritage Tentative List.\n\nFrom bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.\n\nIndia's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh.\n\nThese sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "body_zh": "印度新增三处遗址进入联合国教科文组织世界遗产预备名单。\n\n从安达曼冒泡的泥火山，到马哈纳迪河沿岸古寺，三处印度遗产向全球认可又近一步。\n\n印度常驻联合国教科文组织代表团于 2026 年 10 月 20 日宣布，将安达曼-尼科巴群岛的巴拉唐岩溶泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦的希尔普尔文化考古景观列入预备名单。\n\n这些地点既有活火山、石灰岩洞穴等独特地质，也有体现印度教、佛教与耆那教遗产及多信仰共处的历史寺庙。联邦部长 Gajendra Singh Shekhawat 称赞希尔普尔在艺术、建筑、灵性与学问上的传统；印度目前已有 45 处列入世界遗产名录。", "url": "https://x.com/i/trending/2112826877455053262", "category": "News", "topics": ["Travel"], "updated_at": "2026-10-21T11:43:52.000Z"}, {"id": "2112536423253643495", "domain": "娱乐", "title_en": "Stanford Study Finds California's Wealth Tax Would Lose Billions for State", "title_zh": "加州拟征财富税引反弹，多名亿万富豪迁出", "hook_en": "Seven billionaires, including Google co-founders Larry Page and Sergey Brin, have already left California to dodge the proposed 5% wealth tax. A new Stanford analysis shows this move could cost the state far more than it gains.", "hook_zh": "包括拉里·佩奇、谢尔盖·布林与彼得·蒂尔在内的数十名加州亿万富豪，赶在关键居民身份期限前离开，以规避拟议中的 5% 财富税。", "summary_en": "Economists Benjamin Jaros and Joshua Rauh estimate the one-time tax on billionaires would raise about $30 billion after confirmed exits, but factoring in lost future income taxes from departures results in a net loss of $38.9 billion on average. Across simulations, 85% of outcomes predict fiscal harm, with confirmed leavers like Peter Thiel and Travis Kalanick removing $577.7 billion from the tax base before the 2026 cutoff. Supporters like Sen. Ro Khanna push Prop 40 to fund healthcare for millions, while Gov. Newsom backs Prop 42 to block it amid divided polls near 46% support.", "summary_zh": "第 40 号提案拟对截至 2026 年 1 月 1 日净资产达 10 亿美元及以上的居民按全球净值征税，用于资助 Medi-Cal 医保。斯坦福经济学家在计入迁出效应后，将收入预估下调至约 300 亿美元，远低于最初的 1000 亿美元。仅七起已确认迁出案例所涉净资产就超过 5770 亿美元，或使州政府未来损失约 690 亿美元所得税，净损失接近 390 亿美元。众议员罗·卡纳等支持者称该税对医保至关重要，反对者则强调长期财政收入风险；纽森州长支持的竞争性议案在民调胶着中升温。", "body_en": "California Wealth Tax Faces Backlash as Billionaires Exit State.\n\nDozens of California's billionaires, including Larry Page, Sergey Brin, and Peter Thiel, have left ahead of a key residency deadline, dodging a proposed 5% wealth tax.\n\nProposition 40 aims to tax the worldwide net worth of residents worth $1 billion or more as of January 1, 2026, to fund Medi-Cal healthcare, but Stanford economists now estimate just $30 billion in revenue after accounting for exits—far below the initial $100 billion projection. These departures, representing over $577 billion in net worth from just seven confirmed cases, could cost the state $69 billion in future income taxes, leading to a projected net loss of nearly $39 billion.\n\nWhile supporters like Rep. Ro Khanna defend it as vital for healthcare, opponents highlight the risk to long-term revenues, with a competing measure backed by Gov. Newsom gaining traction amid tight polls.", "body_zh": "加州拟征财富税引反弹，多名亿万富豪迁出。\n\n包括拉里·佩奇、谢尔盖·布林与彼得·蒂尔在内的数十名加州亿万富豪，赶在关键居民身份期限前离开，以规避拟议中的 5% 财富税。\n\n第 40 号提案拟对截至 2026 年 1 月 1 日净资产达 10 亿美元及以上的居民按全球净值征税，用于资助 Medi-Cal 医保。斯坦福经济学家在计入迁出效应后，将收入预估下调至约 300 亿美元，远低于最初的 1000 亿美元。\n\n仅七起已确认迁出案例所涉净资产就超过 5770 亿美元，或使州政府未来损失约 690 亿美元所得税，净损失接近 390 亿美元。众议员罗·卡纳等支持者称该税对医保至关重要，反对者则强调长期财政收入风险；纽森州长支持的竞争性议案在民调胶着中升温。", "url": "https://x.com/i/trending/2112536423253643495", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T12:18:21.000Z"}, {"id": "2112566578415849780", "domain": "娱乐", "title_en": "Copper Supply Shortfall Looms from 2028 Amid Surging Demand", "title_zh": "报告预警：2028 年起铜供应或现巨大缺口", "hook_en": "Copper powers electric vehicles, grids, and AI data centers, but a new report warns of massive shortages starting in 2028 as supply struggles to keep up.", "hook_zh": "铜支撑电动车、电网与 AI 数据中心，新报告警告自 2028 年起供应恐严重跟不上需求。", "summary_en": "BloombergNEF projects copper demand jumping 61% to 46 million tonnes by 2050, driven by electric transport needing 11.4 million tonnes, while supply deficits could hit 20 million tonnes without new investments. Chile, the top producer with 180 million tonnes in reserves, faces slumping output from aging mines, low ore grades, weather, and accidents—potentially dropping to 5 million tonnes by 2026, the lowest in over 20 years. Prices have surged to $14,500 per tonne, with banks forecasting further rises, though closing the gap requires $332 billion and 17 years per new mine.", "summary_zh": "BloombergNEF 预计到 2050 年铜需求增约 61% 至 4600 万吨，其中电动交通约需 1140 万吨；若无足够新投资，供应缺口或达 2000 万吨。头号产国智利储量约 1.8 亿吨，但老龄矿、品位下降、天气与事故或使产量跌向二十多年来低位。铜价已升至约每吨 1.45 万美元，银行看好续涨；新矿山从投建到投产常需约 17 年与巨额资本。", "body_en": "Copper Supply Shortfall Looms from 2028 Amid Surging Demand.\n\nCopper powers electric vehicles, grids, and AI data centers, but a new report warns of massive shortages starting in 2028 as supply struggles to keep up.\n\nBloombergNEF projects copper demand jumping 61% to 46 million tonnes by 2050, driven by electric transport needing 11.4 million tonnes, while supply deficits could hit 20 million tonnes without new investments.\n\nChile, the top producer with 180 million tonnes in reserves, faces slumping output from aging mines, low ore grades, weather, and accidents—potentially dropping to 5 million tonnes by 2026, the lowest in over 20 years. Prices have surged to $14,500 per tonne, with banks forecasting further rises, though closing the gap requires $332 billion and 17 years per new mine.", "body_zh": "报告预警：2028 年起铜供应或现巨大缺口。\n\n铜支撑电动车、电网与 AI 数据中心，新报告警告自 2028 年起供应恐严重跟不上需求。\n\nBloombergNEF 预计到 2050 年铜需求增约 61% 至 4600 万吨，其中电动交通约需 1140 万吨；若无足够新投资，供应缺口或达 2000 万吨。\n\n头号产国智利储量约 1.8 亿吨，但老龄矿、品位下降、天气与事故或使产量跌向二十多年来低位。铜价已升至约每吨 1.45 万美元，银行看好续涨；新矿山从投建到投产常需约 17 年与巨额资本。", "url": "https://x.com/i/trending/2112566578415849780", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T15:35:06.000Z"}, {"id": "2112533925117460907", "domain": "娱乐", "title_en": "BBC to Close BBC Three, BBC Scotland TV and Radio 4 Extra in 2027", "title_zh": "BBC 计划 2027 年关闭 BBC Three、苏格兰台与 Radio 4 Extra 线性频道", "hook_en": "BBC staff heard the tough news from Director-General Matt Brittin: three linear channels will go dark next spring to tackle rising costs and shifting viewer habits.", "hook_zh": "面对财政压力，BBC 将关掉三个线性频道，把内容迁往观众已转向的线上平台。", "summary_en": "The BBC plans to shut down linear broadcasts of BBC Three, BBC Scotland, and Radio 4 Extra by spring 2027, moving them fully online to help save £500 million by 2028 amid financial pressures. This includes cutting over 100 jobs at BBC News and aiming for 1,800 to 2,000 total staff reductions, nearly one in ten positions. Content will stay available on BBC iPlayer, BBC Sounds, and YouTube, with some BBC Scotland shows shifting to BBC One and Two; reactions range from concerns over license fee impacts and harm to public broadcasting to hopes for cuts in other areas.", "summary_zh": "作为到 2028 年节省约 5 亿英镑计划的一部分，BBC 将于 2027 年春结束 BBC Three、BBC Scotland 与 Radio 4 Extra 的广播频道形态，节目更多转至 iPlayer、BBC Sounds 与 YouTube 等。新闻部门拟裁约 100 人节省 550 万英镑，整体目标减员约 1800–2000，背景是收视许可费下降与习惯变迁。总监称要让每英镑更高效；也有议员担忧“千刀万剐”式萎缩。", "body_en": "BBC to Close BBC Three, BBC Scotland and Radio 4 Extra in 2027.\n\nThe BBC faces tough financial calls, shutting down three linear channels next spring to shift content online where audiences are heading.\n\nAs part of a £500 million savings plan by 2028, the BBC will end BBC Three, BBC Scotland, and Radio 4 Extra as broadcast channels in spring 2027, moving much of their programming to iPlayer, BBC Sounds, and platforms like YouTube.\n\nBBC News will cut around 100 jobs to save £5.5 million, with overall workforce reductions targeting 1,800 to 2,000 roles amid declining TV licence payments and changing viewer habits. Director-General Matt Brittin told staff these steps make every pound work harder, while reactions range from Liberal Democrat MP Anna Sabine's concerns over the 'death by a thousand cuts' to others welcoming the changes.", "body_zh": "BBC 计划 2027 年关闭 BBC Three、苏格兰台与 Radio 4 Extra 线性频道。\n\n面对财政压力，BBC 将关掉三个线性频道，把内容迁往观众已转向的线上平台。\n\n作为到 2028 年节省约 5 亿英镑计划的一部分，BBC 将于 2027 年春结束 BBC Three、BBC Scotland 与 Radio 4 Extra 的广播频道形态，节目更多转至 iPlayer、BBC Sounds 与 YouTube 等。\n\n新闻部门拟裁约 100 人节省 550 万英镑，整体目标减员约 1800–2000，背景是收视许可费下降与习惯变迁。总监称要让每英镑更高效；也有议员担忧“千刀万剐”式萎缩。", "url": "https://x.com/i/trending/2112533925117460907", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T18:52:05.000Z"}, {"id": "2112820743943733255", "domain": "娱乐", "title_en": "Philippine Peso Hits New Record Low at P63.361 vs. Dollar", "title_zh": "菲律宾比索再创纪录低位：约 63.361 兑 1 美元", "hook_en": "Filipinos are feeling the pinch as everyday costs climb with the peso's slide—one shared post noted 15 US dollars now fetching nearly 1,000 pesos for groceries and bills.", "hook_zh": "比索续贬，日常开支承压；有人晒出约 15 美元已接近 1000 比索的购物账单。", "summary_en": "On October 21, 2026, the Philippine peso closed at a fresh all-time low of P63.361 against the US dollar, topping the prior day's P63.09 and marking the 29th record low this year amid a strong dollar and global pressures like high oil prices. It dipped to near P63.37 during trading, while the stock index rose slightly to 5,821.51, up 0.26 percent. Freelancers see a silver lining in dollar earnings stretching further, but many voice frustrations over rising import costs for fuel, medicine, and household essentials, prompting calls for economic action.", "summary_zh": "2026 年 10 月 21 日，菲比索收于约 63.361 兑 1 美元，刷新前一日 63.09 的纪录，为本年第 29 次创新低，背景是美元偏强与油价高等全球压力。盘中近 63.37，股市小幅收涨。自由职业者因美元收入“显得更多”而略感安慰，但进口燃料、药品与生活用品成本上升引发不满，呼吁政策应对。", "body_en": "Philippine Peso Hits New Record Low at P63.361 vs. Dollar.\n\nFilipinos are feeling the pinch as everyday costs climb with the peso's slide—one shared post noted 15 US dollars now fetching nearly 1,000 pesos for groceries and bills.\n\nOn October 21, 2026, the Philippine peso closed at a fresh all-time low of P63.361 against the US dollar, topping the prior day's P63.09 and marking the 29th record low this year amid a strong dollar and global pressures like high oil prices.\n\nIt dipped to near P63.37 during trading, while the stock index rose slightly to 5,821.51, up 0.26 percent. Freelancers see a silver lining in dollar earnings stretching further, but many voice frustrations over rising import costs for fuel, medicine, and household essentials, prompting calls for economic action.", "body_zh": "菲律宾比索再创纪录低位：约 63.361 兑 1 美元。\n\n比索续贬，日常开支承压；有人晒出约 15 美元已接近 1000 比索的购物账单。\n\n2026 年 10 月 21 日，菲比索收于约 63.361 兑 1 美元，刷新前一日 63.09 的纪录，为本年第 29 次创新低，背景是美元偏强与油价高等全球压力。\n\n盘中近 63.37，股市小幅收涨。自由职业者因美元收入“显得更多”而略感安慰，但进口燃料、药品与生活用品成本上升引发不满，呼吁政策应对。", "url": "https://x.com/i/trending/2112820743943733255", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T13:03:53.000Z"}, {"id": "2112968038391902349", "domain": "娱乐", "title_en": "YouTube Hits Record 14.2% of U.S. TV Viewing Time", "title_zh": "YouTube 占美国电视收视时长创纪录达 14.2%", "hook_en": "Imagine flipping on the TV and finding YouTube leading the pack—now it's real, pulling ahead of Netflix and old-school networks in living rooms across America.", "hook_zh": "打开电视却发现 YouTube 领跑——如今成真：在全美客厅里它已超过奈飞与传统频道。", "summary_en": "Nielsen's July 2026 Gauge report shows YouTube reaching 14.2% of total U.S. TV time, up from 9% in early 2024, while Netflix slipped to 7.8% from 8.8% a year prior. Streaming overall claimed 49% that month, with YouTube's steady climb outpacing flatter lines from Disney, Paramount, and Warner Bros. Discovery. Observers note this boosts independent creators who upload directly to massive audiences, thanks to low costs, smart algorithms, and nonstop content from millions.", "summary_zh": "尼尔森 2026 年 7 月 Gauge 报告显示，YouTube 占美国电视总收视时长的 14.2%，高于 2024 年初的 9%；奈飞则从一年前的 8.8% 降至 7.8%。当月流媒体整体占 49%，YouTube 稳步攀升，超过迪士尼、派拉蒙与华纳兄弟探索相对平缓的曲线。观察人士指出，低成本、智能算法与数百万创作者持续上传，令独立创作者更易直达大规模受众。", "body_en": "YouTube Hits Record 14.2% of U.S. TV Viewing Time.\n\nImagine flipping on the TV and finding YouTube leading the pack—now it's real, pulling ahead of Netflix and old-school networks in living rooms across America.\n\nNielsen's July 2026 Gauge report shows YouTube reaching 14.2% of total U.S. TV time, up from 9% in early 2024, while Netflix slipped to 7.8% from 8.8% a year prior.\n\nStreaming overall claimed 49% that month, with YouTube's steady climb outpacing flatter lines from Disney, Paramount, and Warner Bros. Discovery. Observers note this boosts independent creators who upload directly to massive audiences, thanks to low costs, smart algorithms, and nonstop content from millions.", "body_zh": "YouTube 占美国电视收视时长创纪录达 14.2%。\n\n打开电视却发现 YouTube 领跑——如今成真：在全美客厅里它已超过奈飞与传统频道。\n\n尼尔森 2026 年 7 月 Gauge 报告显示，YouTube 占美国电视总收视时长的 14.2%，高于 2024 年初的 9%；奈飞则从一年前的 8.8% 降至 7.8%。\n\n当月流媒体整体占 49%，YouTube 稳步攀升，超过迪士尼、派拉蒙与华纳兄弟探索相对平缓的曲线。观察人士指出，低成本、智能算法与数百万创作者持续上传，令独立创作者更易直达大规模受众。", "url": "https://x.com/i/trending/2112968038391902349", "category": "News", "topics": ["Streaming"], "updated_at": "2026-10-21T18:12:11.000Z"}, {"id": "2112891426342424801", "domain": "娱乐", "title_en": "Weak Peso Turns $15 into 1,000 Pesos for Struggling Filipinos", "title_zh": "披索走弱：15 美元约兑 1000 披索，菲律宾人感受「美元红利」", "hook_en": "A simple note that $15 now equals about 1,000 pesos hit home for many, as one creator's tuition plea turned into full coverage from community donations.", "hook_zh": "「15 美元约等于 1000 披索」这句话戳中许多人——一位创作者的学费求助也被社区捐助全部覆盖。", "summary_en": "The Philippine peso reached a record low near 63.36 per dollar this week, its 34th such low in 2026, making small U.S. dollar amounts go much further. Filipino artists, VTubers, and students shared how $15 can now cover two weeks of groceries, bills, or a week's meals, with several opening commissions and tip jars. In one case, donations quickly covered a full semester's 50,000-peso tuition, about $790, bringing real relief amid rising costs.", "summary_zh": "本周菲律宾披索逼近每美元 63.36 的纪录低位，为 2026 年第 34 次刷新低点，令少量美元购买力显著提升。菲律宾艺术家、虚拟主播与学生分享称，15 美元如今可覆盖两周杂货、账单或一周餐费，多人开设约稿与打赏。有一例捐款迅速凑齐一学期约 5 万披索（约 790 美元）学费，在物价上涨中带来切实缓解。", "body_en": "Weak Peso Turns $15 into 1,000 Pesos for Struggling Filipinos.\n\nA simple note that $15 now equals about 1,000 pesos hit home for many, as one creator's tuition plea turned into full coverage from community donations.\n\nThe Philippine peso reached a record low near 63.36 per dollar this week, its 34th such low in 2026, making small U.S. dollar amounts go much further.\n\nFilipino artists, VTubers, and students shared how $15 can now cover two weeks of groceries, bills, or a week's meals, with several opening commissions and tip jars. In one case, donations quickly covered a full semester's 50,000-peso tuition, about $790, bringing real relief amid rising costs.", "body_zh": "披索走弱：15 美元约兑 1000 披索，菲律宾人感受「美元红利」。\n\n「15 美元约等于 1000 披索」这句话戳中许多人——一位创作者的学费求助也被社区捐助全部覆盖。\n\n本周菲律宾披索逼近每美元 63.36 的纪录低位，为 2026 年第 34 次刷新低点，令少量美元购买力显著提升。\n\n菲律宾艺术家、虚拟主播与学生分享称，15 美元如今可覆盖两周杂货、账单或一周餐费，多人开设约稿与打赏。有一例捐款迅速凑齐一学期约 5 万披索（约 790 美元）学费，在物价上涨中带来切实缓解。", "url": "https://x.com/i/trending/2112891426342424801", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T15:54:24.000Z"}, {"id": "2112918023249989711", "domain": "娱乐", "title_en": "Sunshine Benzi Shares Notebook-to-Studio Process for 'Forbes List'", "title_zh": "Sunshine Benzi 分享《Forbes List》从笔记本到录音棚的创作过程", "hook_en": "Sunshine Benzi flips through her notebook in the studio, pen flying as she crafts lyrics for her new track. Fans can't get enough of her hands-on hustle.", "hook_zh": "Sunshine Benzi 在录音棚翻着笔记本奋笔写词，粉丝为她亲力亲为的创作节奏着迷。", "summary_en": "The 24-year-old Chicago-area rapper, born Sunshine Kathleen Holt in Pontiac, Illinois, posted behind-the-scenes clips of writing and recording 'Forbes List,' produced by Bangladesh of Nicki Minaj fame and Chinoo.xo. Viewers praise her raw talent, work ethic, and poetry-rooted approach, with comments like 'this chick can rap' and 'RAW talent' flooding in. She first gained notice in late 2025 with her TikTok freestyle 'Trump the Bill,' followed by singles like 'Barracuda' and a December 2026 Miss Bellum Tour. While some note her background as a white artist in hip-hop, the buzz focuses on her focused craft and building momentum.", "summary_zh": "这位 24 岁、生于伊利诺伊州庞蒂亚克的芝加哥地区说唱歌手 Sunshine Kathleen Holt，晒出创作与录制《Forbes List》的幕后片段，制作人包括曾与 Nicki Minaj 合作的 Bangladesh 以及 Chinoo.xo。观众称赞其原始才华、工作态度与诗歌根底，评论区常见「这姑娘会说唱」「真正的天赋」等话。她 2025 年末因 TikTok 自由说唱《Trump the Bill》走红，随后发行《Barracuda》等单曲，并计划 2026 年 12 月 Miss Bellum 巡演。虽有人提到她作为白人艺人进入嘻哈圈的背景，讨论焦点仍在其专注打磨与持续升温的势头。", "body_en": "Sunshine Benzi Shares Notebook-to-Studio Process for 'Forbes List'.\n\nSunshine Benzi flips through her notebook in the studio, pen flying as she crafts lyrics for her new track. Fans can't get enough of her hands-on hustle.\n\nThe 24-year-old Chicago-area rapper, born Sunshine Kathleen Holt in Pontiac, Illinois, posted behind-the-scenes clips of writing and recording 'Forbes List,' produced by Bangladesh of Nicki Minaj fame and Chinoo.xo. Viewers praise her raw talent, work ethic, and poetry-rooted approach, with comments like 'this chick can rap' and 'RAW talent' flooding in.\n\nShe first gained notice in late 2025 with her TikTok freestyle 'Trump the Bill,' followed by singles like 'Barracuda' and a December 2026 Miss Bellum Tour. While some note her background as a white artist in hip-hop, the buzz focuses on her focused craft and building momentum.", "body_zh": "Sunshine Benzi 分享《Forbes List》从笔记本到录音棚的创作过程。\n\nSunshine Benzi 在录音棚翻着笔记本奋笔写词，粉丝为她亲力亲为的创作节奏着迷。\n\n这位 24 岁、生于伊利诺伊州庞蒂亚克的芝加哥地区说唱歌手 Sunshine Kathleen Holt，晒出创作与录制《Forbes List》的幕后片段，制作人包括曾与 Nicki Minaj 合作的 Bangladesh 以及 Chinoo.xo。观众称赞其原始才华、工作态度与诗歌根底，评论区常见「这姑娘会说唱」「真正的天赋」等话。\n\n她 2025 年末因 TikTok 自由说唱《Trump the Bill》走红，随后发行《Barracuda》等单曲，并计划 2026 年 12 月 Miss Bellum 巡演。虽有人提到她作为白人艺人进入嘻哈圈的背景，讨论焦点仍在其专注打磨与持续升温的势头。", "url": "https://x.com/i/trending/2112918023249989711", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T14:50:09.000Z"}, {"id": "2112078869360726394", "domain": "娱乐", "title_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore", "title_zh": "Kwong Lingling 亮相新加坡卡地亚「Into The Wild」活动", "hook_en": "Lingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.", "hook_zh": "Kwong Lingling 身着闪亮黑色亮片礼服、搭配戏剧感花卉手套，在丛林灵感布景前自信亮相，成为卡地亚雅集焦点。", "summary_en": "On October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry. She stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "summary_zh": "10 月 19 日，泰国女演员 Kwong Lingling 以精致造型出席新加坡卡地亚「Into The Wild」活动，庆祝品牌标志性豹纹与动物灵感珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配粗银链、闪亮手镯与夸张耳环。粉丝盛赞其笑容与气场，有人写道「优雅有了名字」。沉浸式体验 10 月 21 日至 25 日在 17 Rochester Park 对公众开放，部分元素将在 ION Orchard 延续至 11 月初。", "body_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore.\n\nLingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.\n\nOn October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry.\n\nShe stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "body_zh": "Kwong Lingling 亮相新加坡卡地亚「Into The Wild」活动。\n\nKwong Lingling 身着闪亮黑色亮片礼服、搭配戏剧感花卉手套，在丛林灵感布景前自信亮相，成为卡地亚雅集焦点。\n\n10 月 19 日，泰国女演员 Kwong Lingling 以精致造型出席新加坡卡地亚「Into The Wild」活动，庆祝品牌标志性豹纹与动物灵感珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配粗银链、闪亮手镯与夸张耳环。\n\n粉丝盛赞其笑容与气场，有人写道「优雅有了名字」。沉浸式体验 10 月 21 日至 25 日在 17 Rochester Park 对公众开放，部分元素将在 ION Orchard 延续至 11 月初。", "url": "https://x.com/i/trending/2112078869360726394", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T06:02:16.000Z"}, {"id": "2112506238923608157", "domain": "娱乐", "title_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos", "title_zh": "粉丝热捧 Pooh Krittin 与 Pavel Naret 死神题材宣传照", "hook_en": "Pooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.", "hook_zh": "Pooh Krittin 以飘逸黑发与冷调蓝光演绎阴郁死神，Pavel Naret 一身利落白衬衫形成反差——搭档化学反应已跃然纸上。", "summary_en": "The promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama. Fans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "summary_zh": "奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（又称 Fourteen / Rafah），Pavel 饰丧亲麻醉医生 Vivorn Assarak（Won），改编自融合 BL、奇幻、爱情与剧情的网络小说。粉丝狂赞「杀伤力视觉」与「疯狂」配对，有人直呼 Pooh「史上最帅死神」。Change2561 出品，One 31 播出并全球 Netflix 上线；粉丝活动「ROAD TO THE GRIM LOVER」定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "body_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos.\n\nPooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.\n\nThe promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama.\n\nFans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "body_zh": "粉丝热捧 Pooh Krittin 与 Pavel Naret 死神题材宣传照。\n\nPooh Krittin 以飘逸黑发与冷调蓝光演绎阴郁死神，Pavel Naret 一身利落白衬衫形成反差——搭档化学反应已跃然纸上。\n\n奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（又称 Fourteen / Rafah），Pavel 饰丧亲麻醉医生 Vivorn Assarak（Won），改编自融合 BL、奇幻、爱情与剧情的网络小说。\n\n粉丝狂赞「杀伤力视觉」与「疯狂」配对，有人直呼 Pooh「史上最帅死神」。Change2561 出品，One 31 播出并全球 Netflix 上线；粉丝活动「ROAD TO THE GRIM LOVER」定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "url": "https://x.com/i/trending/2112506238923608157", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T11:32:52.000Z"}, {"id": "2112801173090587112", "domain": "娱乐", "title_en": "Thai Actress Lingling Kwong Shines at Cartier’s Into the Wild Event in Singapore", "title_zh": "Lingling Kwong 亮相新加坡卡地亚活动", "hook_en": "Lingling Kwong stepped into a lush garden paradise in Singapore, her shimmering black sequined gown and dramatic gloves catching every light amid animal-inspired jewelry.", "hook_zh": "Lingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。", "summary_en": "Thai actress Lingling Kwong attended Cartier’s “Into the Wild” celebration at Rochester Park as a special guest, wearing striking ensembles from the Faune & Flore collection that blended sequins, floral details, and signature motifs. The event transformed heritage houses and gardens into immersive spaces with illuminated designs, artisan demos, dance performances, and sensory highlights of Cartier’s jewelry, watches, fragrances, and leather goods. Fans and media praised her elegant presence, with the experience open to the public through October 25 at 17 Rochester Park via advance registration.", "summary_zh": "10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "body_en": "Lingling Kwong Shines at Cartier Event in Singapore.\n\nLingling Kwong stepped into Cartier’s wild jungle-themed world in a sleek black sequined gown and dramatic gloves, turning heads with her timeless elegance.\n\nAt the 'Into the Wild' immersive experience in Rochester Park on October 21, Kwong wore pieces from Cartier’s new Faune & Flore collection, featuring onyx, sapphires, and diamonds that fans called striking and queenly.\n\nThe event celebrates the brand’s animal-inspired designs through October 25. That same day, she promoted Her Hyness sunscreen at a big fan event in Bangkok, highlighting her rising star in luxury and beauty.", "body_zh": "Lingling Kwong 亮相新加坡卡地亚活动。\n\nLingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。\n\n10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。\n\n活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "url": "https://x.com/i/trending/2112801173090587112", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T17:57:44.000Z"}, {"id": "2112867591127793782", "domain": "娱乐", "title_en": "Fans Celebrate Glen Powell's 38th Birthday with Warm Tributes", "title_zh": "粉丝暖心祝贺 Glen Powell 38 岁生日", "hook_en": "Glen Powell woke up to a flood of birthday love on his 38th, with fans sharing photos from his suited-up red carpets to early Spy Kids days.", "hook_zh": "Glen Powell 38 岁生日醒来收获海量祝福，粉丝从红毯西装照晒到早年《特工小孩》时期。", "summary_en": "Born October 21, 1988, in Austin, Texas, Powell kicked off his career as a teen in Spy Kids 3-D: Game Over and rose to leading roles in Top Gun: Maverick, Anyone But You, Hit Man—which he co-wrote and produced—and Twisters. Entertainment accounts like Pop Base and Film Updates led the cheers, calling him talented and charming, while fans posted appreciative snaps of his versatile looks and declared it International Glen Powell Day. The outpouring highlights his journey from bit parts in The Dark Knight Rises and Hidden Figures to Hollywood's most watchable stars, with more projects ahead.", "summary_zh": "Powell 1988 年 10 月 21 日生于得州奥斯汀，少年出演《特工小孩 3D》起步，后主演《壮志凌云：独行侠》《爱你，不爱你》《Hit Man》（兼编剧制作）与《龙卷风》。Pop Base、Film Updates 等娱乐账号带头叫好，称其才华与魅力；粉丝晒出多变造型照，并宣称「国际 Glen Powell 日」。从《黑暗骑士崛起》《隐藏人物》龙套到好莱坞最吸睛之一的旅程被再度提起，后续项目仍在路上。", "body_en": "Fans Celebrate Glen Powell's 38th Birthday with Warm Tributes.\n\nGlen Powell woke up to a flood of birthday love on his 38th, with fans sharing photos from his suited-up red carpets to early Spy Kids days.\n\nBorn October 21, 1988, in Austin, Texas, Powell kicked off his career as a teen in Spy Kids 3-D: Game Over and rose to leading roles in Top Gun: Maverick, Anyone But You, Hit Man—which he co-wrote and produced—and Twisters.\n\nEntertainment accounts like Pop Base and Film Updates led the cheers, calling him talented and charming, while fans posted appreciative snaps of his versatile looks and declared it International Glen Powell Day. The outpouring highlights his journey from bit parts in The Dark Knight Rises and Hidden Figures to Hollywood's most watchable stars, with more projects ahead.", "body_zh": "粉丝暖心祝贺 Glen Powell 38 岁生日。\n\nGlen Powell 38 岁生日醒来收获海量祝福，粉丝从红毯西装照晒到早年《特工小孩》时期。\n\nPowell 1988 年 10 月 21 日生于得州奥斯汀，少年出演《特工小孩 3D》起步，后主演《壮志凌云：独行侠》《爱你，不爱你》《Hit Man》（兼编剧制作）与《龙卷风》。\n\nPop Base、Film Updates 等娱乐账号带头叫好，称其才华与魅力；粉丝晒出多变造型照，并宣称「国际 Glen Powell 日」。从《黑暗骑士崛起》《隐藏人物》龙套到好莱坞最吸睛之一的旅程被再度提起，后续项目仍在路上。", "url": "https://x.com/i/trending/2112867591127793782", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T11:29:11.000Z"}, {"id": "2112653365356433717", "domain": "娱乐", "title_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk", "title_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论", "hook_en": "A post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.", "hook_zh": "有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。", "summary_en": "Ariana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office. Seyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "summary_zh": "爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "body_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk.\n\nA post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.\n\nAriana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office.\n\nSeyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "body_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论。\n\n有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。\n\n爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。\n\n粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "url": "https://x.com/i/trending/2112653365356433717", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T00:31:26.000Z"}, {"id": "2112552619117891920", "domain": "科学", "title_en": "Review Details Antiparasitic Drugs' Potential Cancer Mechanisms", "title_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制", "hook_en": "Imagine affordable drugs already on pharmacy shelves quietly targeting cancer in lab studies. A new review compiles dozens of ways ivermectin and mebendazole might disrupt tumor growth.", "hook_zh": "详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。", "summary_en": "Researchers, including Nicolas Hulscher of the McCullough Foundation, released a 44-page paper this week outlining 29 anticancer mechanisms for ivermectin across 20 cancer types and 26 for mebendazole across 17 types. These include halting cell division, triggering cell death, blocking tumor blood vessels, and boosting immune responses, with both drugs showing decades of safety data and low costs. Patient stories highlight hope, like a Polish woman with multiple myeloma seeing no disease markers after six months on ivermectin, fenbendazole, and mebendazole, while an observational group of 197 patients reported an 84.4% clinical benefit rate. Proponents call for clinical trials, but experts stress the need for randomized studies to confirm benefits alongside standard care.", "summary_zh": "McCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "body_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo.\n\nA detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.\n\nResearchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more.\n\nThe 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "body_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制。\n\n详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。\n\nMcCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。\n\n作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "url": "https://x.com/i/trending/2112552619117891920", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-21T17:22:35.000Z"}, {"id": "2112433199888679267", "domain": "科学", "title_en": "AI Predicts Cancer Survival from Face Photos", "title_zh": "AI 凭面部照片预测癌症生存风险", "hook_en": "Doctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.", "hook_zh": "医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。", "summary_en": "Researchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "summary_zh": "麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "body_en": "AI Predicts Cancer Survival from Face Photos.\n\nDoctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.\n\nResearchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation.\n\nWhile promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "body_zh": "AI 凭面部照片预测癌症生存风险。\n\n医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。\n\n麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。\n\n工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "url": "https://x.com/i/trending/2112433199888679267", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T21:07:35.000Z"}, {"id": "2112771430316404992", "domain": "科学", "title_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living", "title_zh": "生物圈 2 号实验再引「自给生存」讨论", "hook_en": "Eight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.", "hook_zh": "1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。", "summary_en": "The $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "summary_zh": "耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "body_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living.\n\nEight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.\n\nThe $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages.\n\nA popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "body_zh": "生物圈 2 号实验再引「自给生存」讨论。\n\n1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。\n\n耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。\n\n热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "url": "https://x.com/i/trending/2112771430316404992", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112514540671730138", "domain": "科学", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade.\n\nPeople share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z"}, {"id": "2112620323275485557", "domain": "科学", "title_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides", "title_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学", "hook_en": "Cancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.", "hook_zh": "同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。", "summary_en": "Holon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests. In tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "summary_zh": "Holon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "body_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides.\n\nCancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.\n\nHolon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests.\n\nIn tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "body_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学。\n\n同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。\n\nHolon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。\n\n联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "url": "https://x.com/i/trending/2112620323275485557", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T01:29:19.000Z"}, {"id": "2112623559876952326", "domain": "科学", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州模拟轨道阳光", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州模拟轨道阳光。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\n10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。\n\n演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z"}, {"id": "2112820742060495085", "domain": "科学", "title_en": "Rizhao Residents Watch Rocket Launch from Home Windows", "title_zh": "日照市民在家门口「看火箭」升空", "hook_en": "People in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.", "hook_zh": "中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。", "summary_en": "On October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit. The satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "summary_zh": "2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "body_en": "Rizhao Residents Watch Rocket Launch from Home Windows.\n\nPeople in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.\n\nOn October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit.\n\nThe satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "body_zh": "日照市民在家门口「看火箭」升空。\n\n中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。\n\n2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。\n\n卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "url": "https://x.com/i/trending/2112820742060495085", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T08:24:00.000Z"}, {"id": "2111892089000915435", "domain": "科学", "title_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds", "title_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道", "hook_en": "Thousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.", "hook_zh": "10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。", "summary_en": "Ruto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units. He inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "summary_zh": "鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "body_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds.\n\nThousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.\n\nRuto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units.\n\nHe inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "body_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道。\n\n10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。\n\n鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。\n\n行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "url": "https://x.com/i/trending/2111892089000915435", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T06:36:12.000Z"}, {"id": "2112802744491000212", "domain": "科学", "title_en": "UN Report: 1.5°C Target Now Requires Overshoot Before Return", "title_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转", "hook_en": "The world has missed the chance to hold global warming below 1.5°C without going over the line first, a new UN report warns. But swift action could still keep the exceedance short and pull temperatures back by 2100.", "hook_zh": "联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。", "summary_en": "The UN Environment Programme's Emissions Gap Report states that current policies point to up to 2.8°C of warming by century's end, while national pledges would limit it to 2.6°C. To minimize overshoot to 1.7-1.8°C mid-century with a fair shot at returning to 1.5°C by 2100, emissions must drop 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels. Key steps include tripling renewable electricity, slashing coal power by 75%, and cutting methane by 25%, as UN leaders like António Guterres urge pulling back from the brink ahead of COP31.", "summary_zh": "联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。UNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "body_en": "UN Report: 1.5°C Limit Overshoot Now Inevitable.\n\nYears of slow action have closed the door on staying below 1.5°C warming without a temporary breach. The focus shifts to limiting how high and how long temperatures climb before dropping back.\n\nThe UN Environment Programme’s 2026 Emissions Gap Report states that global warming will exceed the Paris Agreement’s 1.5°C target in coming years, with the best-case peak at 1.7–1.8°C mid-century and a 50% chance of returning below 1.5°C by 2100. This requires emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus large-scale carbon removal.\n\nCurrent pledges only achieve 5–8% cuts by 2030, heading toward 2.6°C or more warming. UNEP’s Inger Andersen calls for urgent action to minimize risks like floods and heatwaves ahead of COP31 talks.", "body_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转。\n\n联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。\n\n联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。\n\nUNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T16:57:31.000Z"}, {"id": "2112240832162005347", "domain": "科学", "title_en": "Russian Satellite Stalks U.S. Radar Craft Aiding Ukraine", "title_zh": "俄军卫星抵近跟踪助乌美系雷达卫星", "hook_en": "A Russian military satellite crept within kilometers of a U.S.-owned radar satellite that helps Ukraine's forces with imaging intel, then backed off after days of close tracking.", "hook_zh": "一颗俄军卫星一度逼近为乌军提供成像情报的美资雷达卫星至数公里内，跟踪数日后撤离。", "summary_en": "Kosmos-2612, launched in April 2026, spent weeks adjusting its orbit to approach ICEYE-X36, a Finnish-American satellite providing all-weather radar images to Ukraine. Public data showed it closing to within a few kilometers by mid-October, station-keeping nearby for two days in what analysts called the first unapproved rendezvous of active low-Earth orbit satellites. LeoLabs tracked it as close as 500 meters at times, allowing potential reconnaissance from multiple angles, though ICEYE confirmed no damage and Russia offered no comment. The satellite pulled away on October 18, highlighting rising tensions where commercial space assets support military efforts.", "summary_zh": "2026 年 4 月发射的「宇宙-2612」数周调整轨道，接近芬兰—美国的 ICEYE-X36——该星为乌克兰提供全天候雷达图像。公开数据显示，至 10 月中旬它靠近至数公里内，并在附近驻留约两天，分析人士称之为活跃近地轨道卫星首次未经批准的交会。LeoLabs 追踪显示最近时距约 500 米，具备多角度侦察可能；ICEYE 确认未受损，俄方未置评。该星于 10 月 18 日离开，凸显商业太空资产支援军事行动下的紧张升温。", "body_en": "Russian Satellite Stalks U.S. Radar Craft Aiding Ukraine.\n\nA Russian military satellite crept within kilometers of a U.S.-owned radar satellite that helps Ukraine's forces with imaging intel, then backed off after days of close tracking.\n\nKosmos-2612, launched in April 2026, spent weeks adjusting its orbit to approach ICEYE-X36, a Finnish-American satellite providing all-weather radar images to Ukraine. Public data showed it closing to within a few kilometers by mid-October, station-keeping nearby for two days in what analysts called the first unapproved rendezvous of active low-Earth orbit satellites.\n\nLeoLabs tracked it as close as 500 meters at times, allowing potential reconnaissance from multiple angles, though ICEYE confirmed no damage and Russia offered no comment. The satellite pulled away on October 18, highlighting rising tensions where commercial space assets support military efforts.", "body_zh": "俄军卫星抵近跟踪助乌美系雷达卫星。\n\n一颗俄军卫星一度逼近为乌军提供成像情报的美资雷达卫星至数公里内，跟踪数日后撤离。\n\n2026 年 4 月发射的「宇宙-2612」数周调整轨道，接近芬兰—美国的 ICEYE-X36——该星为乌克兰提供全天候雷达图像。公开数据显示，至 10 月中旬它靠近至数公里内，并在附近驻留约两天，分析人士称之为活跃近地轨道卫星首次未经批准的交会。\n\nLeoLabs 追踪显示最近时距约 500 米，具备多角度侦察可能；ICEYE 确认未受损，俄方未置评。该星于 10 月 18 日离开，凸显商业太空资产支援军事行动下的紧张升温。", "url": "https://x.com/i/trending/2112240832162005347", "category": "News", "topics": ["Space"], "updated_at": "2026-10-20T15:54:21.000Z"}, {"id": "2112968032066920582", "domain": "科学", "title_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted", "title_zh": "回顾生物圈 2 号氧气危机与混乱任务", "hook_en": "Eight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.", "hook_zh": "八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。", "summary_en": "Biosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk. Pigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "summary_zh": "造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。", "body_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted.\n\nEight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.\n\nBiosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk.\n\nPigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "body_zh": "回顾生物圈 2 号氧气危机与混乱任务。\n\n八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。\n\n造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。\n\n猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。", "url": "https://x.com/i/trending/2112968032066920582", "category": "News", "topics": ["News", "Science"], "updated_at": "2026-10-21T18:10:40.000Z"}, {"id": "2112160143613874580", "domain": "科学", "title_en": "Trump Signs Order for NIH Women’s Health Division and Task Force", "title_zh": "特朗普签署行政令，设立 NIH 女性健康分部与白宫工作组", "hook_en": "First Lady Melania Trump stood beside President Trump as he signed the executive order, calling it a transformative moment for women's health in America.", "hook_zh": "第一夫人梅拉尼娅陪同总统签署面向女性健康的行政令。", "summary_en": "On October 19, President Donald Trump signed an executive order establishing a new Women’s Health Division at the National Institutes of Health and a White House task force co-led by Chief of Staff Susie Wiles and HHS Secretary Robert F. Kennedy Jr. The initiative targets research gaps in conditions like osteoporosis, Alzheimer’s, heart disease, endometriosis, and maternal health, with the division to launch within 90 days. Melania Trump outlined five pillars for innovation, including AI-driven discoveries and affordable therapies, while Wiles shared how her breast cancer experience made early detection personal.", "summary_zh": "行政令设立 NIH 女性健康分部与白宫工作组，聚焦骨质疏松、阿尔茨海默病、心脏病、子宫内膜异位症与孕产妇健康等。", "body_en": "First Lady Melania Trump stood beside President Trump as he signed the executive order, calling it a transformative moment for women's health in America.\n\nOn October 19, President Donald Trump signed an executive order establishing a new Women’s Health Division at the National Institutes of Health and a White House task force co-led by Chief of Staff Susie Wiles and HHS Secretary Robert F. Kennedy Jr.\n\nThe initiative targets research gaps in conditions like osteoporosis, Alzheimer’s, heart disease, endometriosis, and maternal health, with the division to launch within 90 days. Melania Trump outlined five pillars for innovation, including AI-driven discoveries and affordable therapies, while Wiles shared how her breast cancer experience made early detection personal.", "body_zh": "10 月 19 日，特朗普签署行政令，在国立卫生研究院设立女性健康司，并由幕僚长苏茜·威尔斯与卫生部长小罗伯特·肯尼迪共同领导白宫工作组。第一夫人梅拉尼娅称这是美国女性健康的变革时刻。\n\n倡议瞄准骨质疏松、阿尔茨海默病、心脏病、子宫内膜异位症与孕产妇健康等研究缺口，司局拟 90 天内启动。梅拉尼娅提出含 AI 驱动发现与可负担疗法等五大创新支柱。\n\n威尔斯分享乳腺癌经历，强调早筛对她个人意义重大，为政策增添现实注脚。", "url": "https://x.com/i/trending/2112160143613874580", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T01:11:38.000Z"}, {"id": "2112891430113075386", "domain": "科学", "title_en": "CHOP's Sedated Flu Shots for Kids Draw Doctor Backlash", "title_zh": "费城儿童医院麻醉中接种流感疫苗引医生与家长反弹", "hook_en": "Picture a child already under anesthesia for surgery—then getting a flu shot without waking up. CHOP says it helps fearful kids, but doctors call it risky.", "hook_zh": "费城一家儿童医院开始在患儿已接受麻醉做手术时顺带打流感针，帮数千人避开针头恐惧——但有医生称这是危险赌博。", "summary_en": "Children's Hospital of Philadelphia started its 'Close Your Eyes, We'll Immunize' program in 2023 to give flu shots to sedated kids during procedures, delivering 2,054 doses in the 2025-2026 season. About one-third of families said their child wouldn't have gotten the vaccine otherwise, and CHOP reports no serious complications. Critics like anesthesiologist Madhava Setty, who trained there, argue it adds unnecessary risks such as fevers or allergic reactions that could mimic other issues under anesthesia. The debate highlights tensions between boosting vaccination rates and ensuring safety during surgery.", "summary_zh": "费城儿童医院自 2023 年推出「闭上眼睛，我们来接种」计划，2025–2026 季已向镇静患儿接种逾 2000 剂流感疫苗。约三分之一家庭表示孩子本会因怕针或其他障碍跳过接种，此举亦契合疾控中心与美国儿科学会「能打就打」的指导。麻醉科医生 Madhava Setty 等批评者称「惊人地不负责任」，担忧发烧混淆麻醉反应或术中罕见过敏；院方称未见严重并发症，并允许家庭选择退出。科罗拉多儿童医院等类似项目自 2020 年以来已为逾 1.8 万名儿童接种。", "body_en": "CHOP's Anesthesia Flu Shots Draw Doctor and Parent Backlash.\n\nA Philadelphia children's hospital started giving flu shots to kids already under anesthesia for procedures, helping thousands avoid needles—but doctors are calling it a dangerous gamble.\n\nChildren's Hospital of Philadelphia launched its 'Close Your Eyes, We'll Immunize' program in 2023, delivering over 2,000 flu vaccine doses during the 2025-2026 season to sedated pediatric patients. About one-third of families said their child would have skipped the shot due to needle fears or other barriers, aligning with CDC and AAP guidance to vaccinate whenever possible.\n\nCritics like anesthesiologist Madhava Setty call it 'stunningly irresponsible' over risks like fevers mimicking anesthesia reactions or rare allergies during surgery, while CHOP reports no serious complications and notes families can opt out. Similar programs at places like Children's Hospital Colorado have vaccinated over 18,000 kids since 2020.", "body_zh": "费城儿童医院麻醉中接种流感疫苗引医生与家长反弹。\n\n费城一家儿童医院开始在患儿已接受麻醉做手术时顺带打流感针，帮数千人避开针头恐惧——但有医生称这是危险赌博。\n\n费城儿童医院自 2023 年推出「闭上眼睛，我们来接种」计划，2025–2026 季已向镇静患儿接种逾 2000 剂流感疫苗。约三分之一家庭表示孩子本会因怕针或其他障碍跳过接种，此举亦契合疾控中心与美国儿科学会「能打就打」的指导。\n\n麻醉科医生 Madhava Setty 等批评者称「惊人地不负责任」，担忧发烧混淆麻醉反应或术中罕见过敏；院方称未见严重并发症，并允许家庭选择退出。科罗拉多儿童医院等类似项目自 2020 年以来已为逾 1.8 万名儿童接种。", "url": "https://x.com/i/trending/2112891430113075386", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-21T17:58:54.000Z"}]};
